// Cloudflare Worker — serves the SolarWinds Sizing calculator
const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>SolarWinds License &amp; Hardware Sizing Calculators</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Google+Sans+Flex:opsz,wght@6..144,300..700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --artifact-background:#ffffff;--artifact-background-light:#f1f3f6;--artifact-background-mid:#e9ecf1;\n  --artifact-border-light:#e3e6ec;--artifact-border-dark:#cdd2db;--artifact-primary-brand:#3559e6;\n  --artifact-primary-highlight:#0d0f14;--artifact-primary-hover:#2442b8;--artifact-selected:#eaeefc;\n  --artifact-text-primary:#11141a;--artifact-text-secondary:#5c6470;--artifact-text-highlight:#e8eefc;\n  --artifact-positive-background:#e8f6ee;--artifact-positive-text:#11141a;--artifact-positive:#159a6a;\n  --artifact-negative:#dc4c4c;--artifact-warn-bg:#fbf3e2;\n}\nhtml[data-theme='dark']{\n  --artifact-background:#0a0b0e;--artifact-background-light:#121419;--artifact-background-mid:#181b22;\n  --artifact-border-light:#23262e;--artifact-border-dark:#343844;--artifact-primary-brand:#6a92ff;\n  --artifact-primary-highlight:#f5f7fb;--artifact-primary-hover:#88a8ff;--artifact-selected:#1a2030;\n  --artifact-text-primary:#eef0f4;--artifact-text-secondary:#9aa0ad;--artifact-text-highlight:#14213d;\n  --artifact-positive-background:#0e2a1d;--artifact-positive-text:#c8f5da;--artifact-positive:#46d39a;\n  --artifact-negative:#ff6b6b;--artifact-warn-bg:#25200f;\n}\n*{box-sizing:border-box}\nbody{font-family:\"Google Sans Flex\",\"Google Sans\",\"Product Sans\",\"Inter\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;letter-spacing:-.005em;background:var(--artifact-background);color:var(--artifact-text-primary);margin:0;padding:0}\n.shell{max-width:1100px;margin:0 auto;padding:48px 28px 90px}\n.eyebrow{font-family:\"SF Mono\",\"IBM Plex Mono\",\"Consolas\",monospace;font-size:12px;font-weight:500;letter-spacing:.12em;text-transform:uppercase;color:var(--artifact-text-secondary);margin:0 0 12px}\nh1{font-size:clamp(2rem,4.4vw,3rem);font-weight:300;line-height:1.05;letter-spacing:-.02em;margin:0 0 14px}\n.sub{color:var(--artifact-text-secondary);max-width:770px;margin:0 0 34px}\nh2{font-size:1.4rem;font-weight:500;margin:0 0 4px}\n.section-tag{font-family:\"SF Mono\",\"IBM Plex Mono\",\"Consolas\",monospace;font-size:12px;font-weight:500;letter-spacing:.12em;text-transform:uppercase;color:var(--artifact-primary-brand);margin:0 0 6px}\n.layout{display:grid;grid-template-columns:1fr 1fr;gap:26px;align-items:start}\n@media(max-width:900px){.layout{grid-template-columns:1fr}}\n.panel{background:var(--artifact-background-light);border:1px solid var(--artifact-border-light);border-radius:8px;padding:24px}\n.panel-title{font-family:\"SF Mono\",\"IBM Plex Mono\",\"Consolas\",monospace;font-size:12px;font-weight:500;letter-spacing:.12em;text-transform:uppercase;color:var(--artifact-text-secondary);margin:0 0 18px;padding-bottom:10px;border-bottom:1px solid var(--artifact-border-light)}\n.field{margin-bottom:18px}\n.field-label{display:block;font-size:14px;font-weight:500;margin-bottom:5px}\n.field-hint{font-size:12.5px;color:var(--artifact-text-secondary);margin:2px 0 8px}\ninput[type=number]{width:100%;padding:10px 12px;font-size:15px;font-family:inherit;border:1px solid var(--artifact-border-dark);border-radius:6px;background:var(--artifact-background);color:var(--artifact-text-primary);font-variant-numeric:tabular-nums}\ninput[type=number]:focus{outline:none;border-color:var(--artifact-primary-brand)}\n.row2{display:grid;grid-template-columns:1fr 1fr;gap:14px}\n.seg{display:flex;gap:8px;flex-wrap:wrap}\n.seg button{flex:1;min-width:72px;padding:9px 8px;font-size:13px;font-family:inherit;font-weight:500;border:1px solid var(--artifact-border-dark);border-radius:6px;background:var(--artifact-background);color:var(--artifact-text-secondary);cursor:pointer;transition:.15s}\n.seg button.active{background:var(--artifact-selected);border-color:var(--artifact-primary-brand);color:var(--artifact-primary-brand)}\n.explainer{border-radius:6px;padding:12px 14px;font-size:13px;border:1px solid var(--artifact-border-light);background:var(--artifact-background);margin-bottom:20px}\n.sub-head{font-family:\"SF Mono\",\"IBM Plex Mono\",\"Consolas\",monospace;font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--artifact-text-secondary);margin:22px 0 12px;padding-top:14px;border-top:1px dashed var(--artifact-border-light)}\n.result-hero{background:var(--artifact-text-highlight);border:1px solid var(--artifact-border-light);border-radius:8px;padding:24px;margin-bottom:18px}\n.metric{font-weight:300;font-size:clamp(2.4rem,5.5vw,3.4rem);line-height:1;letter-spacing:-.03em;font-variant-numeric:tabular-nums;margin:6px 0 2px}\n.metric small{font-size:1.05rem;color:var(--artifact-text-secondary);font-weight:400}\n.badge{display:inline-block;font-family:\"SF Mono\",\"IBM Plex Mono\",\"Consolas\",monospace;font-size:11px;letter-spacing:.1em;text-transform:uppercase;padding:4px 9px;border-radius:4px;background:var(--artifact-primary-brand);color:#fff;margin-top:8px}\nhtml[data-theme='dark'] .badge{color:#0a0b0e}\n.grid-out{display:grid;grid-template-columns:1fr 1fr;gap:14px}\n.out-card{background:var(--artifact-background);border:1px solid var(--artifact-border-light);border-radius:8px;padding:15px 17px}\n.out-label{font-size:12.5px;color:var(--artifact-text-secondary);margin-bottom:4px;display:flex;align-items:center;gap:6px}\n.out-value{font-size:1.4rem;font-weight:400;font-variant-numeric:tabular-nums;letter-spacing:-.01em}\n.out-value small{font-size:.82rem;color:var(--artifact-text-secondary)}\n.note{font-size:12.5px;color:var(--artifact-text-secondary);margin-top:7px;line-height:1.5}\n.flag{border-radius:6px;padding:11px 14px;font-size:13.5px;margin-top:12px;border:1px solid var(--artifact-border-light)}\n.flag.warn{background:var(--artifact-warn-bg)}\n.flag.pos{background:var(--artifact-positive-background);color:var(--artifact-positive-text)}\n.info{position:relative;display:inline-flex;cursor:help;color:var(--artifact-text-secondary)}\n.info .ico{width:14px;height:14px;border:1px solid var(--artifact-border-dark);border-radius:50%;font-size:10px;line-height:12px;text-align:center;font-family:monospace}\n.info .tip{visibility:hidden;opacity:0;position:absolute;bottom:135%;left:50%;transform:translateX(-50%);width:240px;background:var(--artifact-primary-highlight);color:var(--artifact-background);font-size:12px;line-height:1.45;padding:9px 11px;border-radius:6px;z-index:30;transition:opacity .15s;text-transform:none;letter-spacing:0;font-weight:400}\n.info:hover .tip,.info:focus .tip{visibility:visible;opacity:1}\n.block{margin-top:46px}\ntable{width:100%;border-collapse:collapse;font-size:13.5px}\nth{font-family:\"SF Mono\",\"IBM Plex Mono\",\"Consolas\",monospace;font-size:11px;font-weight:500;letter-spacing:.08em;text-transform:uppercase;color:var(--artifact-text-secondary);text-align:left;padding:9px 11px;border-bottom:1px solid var(--artifact-border-dark)}\ntd{padding:9px 11px;border-bottom:1px solid var(--artifact-border-light);font-variant-numeric:tabular-nums}\ntr.hit td{background:var(--artifact-selected)}\nth.hit,td.hit{background:var(--artifact-selected);color:var(--artifact-primary-brand)}\n.yes{color:var(--artifact-positive);font-weight:600}\n.no{color:var(--artifact-text-secondary)}\n.hw-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}\n@media(max-width:900px){.hw-grid{grid-template-columns:1fr}}\n.hw-card{border:1px solid var(--artifact-border-light);border-radius:8px;padding:20px;background:var(--artifact-background-light)}\n.hw-card h3{font-size:1.15rem;font-weight:500;margin:0 0 2px}\n.hw-card .cap{font-size:12.5px;color:var(--artifact-text-secondary);margin-bottom:14px}\n.grp{font-family:\"SF Mono\",\"IBM Plex Mono\",\"Consolas\",monospace;font-size:10.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--artifact-primary-brand);margin:16px 0 6px}\n.assump ul{padding-left:18px;color:var(--artifact-text-secondary);font-size:14px}\n.assump li{margin-bottom:8px}\n.assump a{color:var(--artifact-primary-brand)}\ndetails{margin-top:12px;border:1px solid var(--artifact-border-light);border-radius:6px;padding:10px 14px}\nsummary{cursor:pointer;font-weight:500;font-size:14px}\n.foot-note{font-size:12px;color:var(--artifact-text-secondary);margin-top:28px}\n@media print{\n  body{margin:0;padding:.4in .55in;background:#fff;print-color-adjust:exact;-webkit-print-color-adjust:exact}\n  .shell{max-width:100%!important;width:100%!important}\n  .panel,.out-card,.result-hero,.hw-card{break-inside:avoid;box-shadow:none!important}\n  table,tr{break-inside:avoid}\n  button,[role=button]{display:none!important}\n  .seg button.active{display:inline-block!important}\n  *,*::before,*::after{animation:none!important;transition:none!important}\n}\n\n/* --- merged from SWO SaaS calculator --- */\n.checkbox-field .check{display:flex;align-items:center;gap:9px;font-size:14px;font-weight:500;cursor:pointer;margin-bottom:4px}\n.checkbox-field input[type=checkbox]{width:17px;height:17px;accent-color:var(--artifact-primary-brand);cursor:pointer}\n#sw-uptime-preview{font-size:13px;font-weight:500}\ntr.total td{font-weight:600;border-top:2px solid var(--artifact-border-dark);background:var(--artifact-background-light)}\n/* --- merged from Premier calculator --- */\n.row3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px}\n/* --- brand block --- */\n.brand{display:flex;flex-direction:column;justify-content:center;margin-right:auto;padding-right:16px;line-height:1.25}\n.brand-title{font-weight:600;font-size:15px;letter-spacing:-.01em;color:var(--artifact-text-primary)}\n.brand-sub{font-family:\"SF Mono\",\"IBM Plex Mono\",\"Consolas\",monospace;font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--artifact-text-secondary)}\n/* --- tab navigation --- */\n.tab-bar{position:sticky;top:0;z-index:50;align-items:center;background:var(--artifact-background);border-bottom:1px solid var(--artifact-border-light);display:flex;gap:8px;flex-wrap:wrap;max-width:1100px;margin:0 auto;padding:14px 28px}\n.tab-btn{padding:9px 16px;font-size:13.5px;font-family:inherit;font-weight:500;border:1px solid var(--artifact-border-dark);border-radius:6px;background:var(--artifact-background);color:var(--artifact-text-secondary);cursor:pointer;transition:.15s}\n.tab-btn.active{background:var(--artifact-selected);border-color:var(--artifact-primary-brand);color:var(--artifact-primary-brand)}\n.tab-panel{display:none}\n.tab-panel.active{display:block}\n/* --- contact strip --- */\n.contact-strip{margin-top:12px;display:grid;grid-template-columns:1fr 1fr;gap:14px}\n.contact-head{margin:18px 0 0;border-top:1px dashed var(--artifact-border-light)}\n.contact-card{border:1px solid var(--artifact-border-light);border-radius:8px;background:var(--artifact-background);padding:15px 17px;display:flex;flex-direction:column;line-height:1.5}\n.contact-card .c-role{font-family:\"SF Mono\",\"IBM Plex Mono\",\"Consolas\",monospace;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:var(--artifact-text-secondary)}\n.contact-card .c-name{font-size:14px;font-weight:600}\n.contact-card a{font-size:12.5px;color:var(--artifact-primary-brand);text-decoration:none}\n.contact-card a:hover{text-decoration:underline}\n/* --- language toggle --- */\n.lang-seg{display:flex;gap:6px;margin-left:10px;padding-left:12px;border-left:1px solid var(--artifact-border-light)}\n.lang-btn{padding:9px 12px;font-size:12.5px;font-family:inherit;font-weight:600;letter-spacing:.04em;border:1px solid var(--artifact-border-dark);border-radius:6px;background:var(--artifact-background);color:var(--artifact-text-secondary);cursor:pointer;transition:.15s}\n.lang-btn.active{background:var(--artifact-selected);border-color:var(--artifact-primary-brand);color:var(--artifact-primary-brand)}\n@media print{.tab-bar{display:none!important}.tab-panel{display:none!important}.tab-panel.active{display:block!important}}\n</style>\n</head>\n<body>\n<nav class=\"tab-bar\" aria-label=\"Calculator selector\">\n<div class=\"brand\">\n  <span class=\"brand-title\">SolarWinds Sizing</span>\n  <span class=\"brand-sub\">by Westcon ID Team</span>\n</div>\n<button class=\"tab-btn active\" data-tab=\"sw\">SWO SaaS</button>\n<button class=\"tab-btn\" data-tab=\"ea\">OSH Essentials & Advanced</button>\n<button class=\"tab-btn\" data-tab=\"pr\">OSH Premier</button>\n<button class=\"tab-btn\" data-tab=\"dpa\">DPA</button>\n<div class=\"lang-seg\" aria-label=\"Language\">\n<button class=\"lang-btn active\" data-lang=\"en\">EN</button>\n<button class=\"lang-btn\" data-lang=\"id\">ID</button>\n</div>\n</nav>\n<section class=\"tab-panel active\" id=\"panel-sw\">\n<div class=\"shell\">\n  <p class=\"eyebrow\">SolarWinds \u00b7 Solutions Engineering \u00b7 APJ</p>\n  <h1 data-glean-id=\"title\">SolarWinds Observability SaaS<br>License &amp; Sizing Calculator</h1>\n  <p class=\"sub\" data-glean-id=\"intro\">Size a full-stack SolarWinds Observability SaaS subscription across all modules \u2014 Network, Infrastructure, Application (APM), Database, Digital Experience (Synthetics &amp; RUM), and Logs \u2014 using the \u00e0-la-carte, entity/consumption-based model. This calculator returns <strong>licensable quantities only</strong> (no pricing). Because the SaaS backend is hosted by SolarWinds, the only customer-side \"hardware\" to size is the collectors and agents that ship telemetry to the cloud.</p>\n\n  <div class=\"layout\">\n    <!-- INPUTS -->\n    <div class=\"panel\" data-glean-id=\"inputs\">\n      <p class=\"panel-title\">Monitoring scope (entities)</p>\n      <div class=\"explainer\" data-glean-id=\"how-counting\">\n        <strong>How SaaS licensing counts things:</strong> each module is licensed separately by the number of active entities (or consumption) monitored in the previous calendar day. Smaller resources share an entitlement \u2014 VMs 3:1, cloud services 3:1, containers &amp; wireless APs 10:1. ICMP-only status nodes are included free.\n      </div>\n\n      <p class=\"sub-head\">Network &amp; Infrastructure Observability</p>\n      <div class=\"row2\">\n        <div class=\"field\"><label class=\"field-label\" for=\"sw-i-netdev\">Network devices</label><p class=\"field-hint\">Routers, switches, firewalls (1:1).</p><input type=\"number\" id=\"sw-i-netdev\" min=\"0\" value=\"300\"></div>\n        <div class=\"field\"><label class=\"field-label\" for=\"sw-i-aps\">Wireless APs</label><p class=\"field-hint\">10 share 1 entitlement.</p><input type=\"number\" id=\"sw-i-aps\" min=\"0\" value=\"0\"></div>\n      </div>\n      <div class=\"row2\">\n        <div class=\"field\"><label class=\"field-label\" for=\"sw-i-hosts\">Hosts / servers</label><p class=\"field-hint\">Agent or collector (1:1).</p><input type=\"number\" id=\"sw-i-hosts\" min=\"0\" value=\"200\"></div>\n        <div class=\"field\"><label class=\"field-label\" for=\"sw-i-hv\">Hypervisors / virtual hosts</label><p class=\"field-hint\">VMware/Hyper-V/Nutanix host (1:1).</p><input type=\"number\" id=\"sw-i-hv\" min=\"0\" value=\"0\"></div>\n      </div>\n      <div class=\"row2\">\n        <div class=\"field\"><label class=\"field-label\" for=\"sw-i-vms\">Standalone VMs</label><p class=\"field-hint\">3 share 1 entitlement.</p><input type=\"number\" id=\"sw-i-vms\" min=\"0\" value=\"0\"></div>\n        <div class=\"field\"><label class=\"field-label\" for=\"sw-i-cloud\">Cloud services (non-host)</label><p class=\"field-hint\">AWS/Azure services, 3:1.</p><input type=\"number\" id=\"sw-i-cloud\" min=\"0\" value=\"0\"></div>\n      </div>\n      <div class=\"row2\">\n        <div class=\"field\"><label class=\"field-label\" for=\"sw-i-containers\">Kubernetes containers</label><p class=\"field-hint\">10 share 1 entitlement.</p><input type=\"number\" id=\"sw-i-containers\" min=\"0\" value=\"0\"></div>\n        <div class=\"field\"><label class=\"field-label\" for=\"sw-i-storage\">Storage arrays</label><p class=\"field-hint\">1:1.</p><input type=\"number\" id=\"sw-i-storage\" min=\"0\" value=\"0\"></div>\n      </div>\n      <div class=\"field\"><label class=\"field-label\" for=\"sw-i-flows\">NetFlow flows/sec (optional)</label><p class=\"field-hint\">Drives dedicated flow collector sizing (\u226440,000 FPS each).</p><input type=\"number\" id=\"sw-i-flows\" min=\"0\" value=\"0\"></div>\n\n      <p class=\"sub-head\">Applications &amp; Databases</p>\n      <div class=\"row2\">\n        <div class=\"field\"><label class=\"field-label\" for=\"sw-i-apm\">APM services</label><p class=\"field-hint\">Per active service, any # instances.</p><input type=\"number\" id=\"sw-i-apm\" min=\"0\" value=\"0\"></div>\n        <div class=\"field\"><label class=\"field-label\" for=\"sw-i-db\">Database instances</label><p class=\"field-hint\">Per active instance.</p><input type=\"number\" id=\"sw-i-db\" min=\"0\" value=\"0\"></div>\n      </div>\n\n      <p class=\"sub-head\">Digital Experience \u2014 Synthetic Uptime</p>\n      <div class=\"explainer\" data-glean-id=\"how-uptime\">\n        <strong>Uptime checks = endpoints \u00d7 locations \u00d7 protocols.</strong> e.g. 20 endpoints \u00d7 2 locations \u00d7 1 protocol = 40 uptime checks. Each private probe you deploy counts as an additional location, so private probes are added to the location count before multiplying.\n      </div>\n      <div class=\"row2\">\n        <div class=\"field\"><label class=\"field-label\" for=\"sw-i-endpoints\">Endpoints / URLs</label><p class=\"field-hint\">Distinct targets to monitor.</p><input type=\"number\" id=\"sw-i-endpoints\" min=\"0\" value=\"20\"></div>\n        <div class=\"field\"><label class=\"field-label\" for=\"sw-i-protocols\">Protocols per endpoint</label><p class=\"field-hint\">e.g. HTTP(S), TCP, ICMP, DNS.</p><input type=\"number\" id=\"sw-i-protocols\" min=\"0\" value=\"1\"></div>\n      </div>\n      <div class=\"field\"><label class=\"field-label\" for=\"sw-i-locations\">Public probe locations</label><p class=\"field-hint\">SolarWinds cloud test locations.</p><input type=\"number\" id=\"sw-i-locations\" min=\"0\" value=\"2\"></div>\n      <div class=\"field checkbox-field\">\n        <label class=\"check\"><input type=\"checkbox\" id=\"sw-i-usepp\"> <span>Use private probes</span></label>\n        <p class=\"field-hint\">Agent-based probes hosted inside the customer network for internal endpoints.</p>\n      </div>\n      <div class=\"field\" id=\"sw-pp-wrap\" style=\"display:none\">\n        <label class=\"field-label\" for=\"sw-i-pp\">Number of private probes</label>\n        <p class=\"field-hint\">Added to location count. Each probe is a customer-hosted test location.</p>\n        <input type=\"number\" id=\"sw-i-pp\" min=\"0\" value=\"0\">\n      </div>\n      <div class=\"explainer\" id=\"sw-uptime-preview\" style=\"border-color:var(--artifact-primary-brand)\"></div>\n\n      <p class=\"sub-head\">Digital Experience \u2014 Transactions &amp; RUM</p>\n      <div class=\"field\"><label class=\"field-label\" for=\"sw-i-txn\">Synthetic transactions</label><p class=\"field-hint\">Scripted multi-step journeys. 2 / bundle (5 checks each).</p><input type=\"number\" id=\"sw-i-txn\" min=\"0\" value=\"0\"></div>\n      <div class=\"field\"><label class=\"field-label\" for=\"sw-i-rum\">RUM pageviews / month</label><p class=\"field-hint\">Bundles of 100,000 pageviews.</p><input type=\"number\" id=\"sw-i-rum\" min=\"0\" value=\"0\"></div>\n\n      <p class=\"sub-head\">Logs</p>\n      <div class=\"field\"><label class=\"field-label\" for=\"sw-i-logs\">Log ingest (GB / day)</label><p class=\"field-hint\">Priced per GB/day; org ceiling \u2248 200 GB/hr.</p><input type=\"number\" id=\"sw-i-logs\" min=\"0\" value=\"0\"></div>\n    </div>\n\n    <!-- OUTPUTS -->\n    <div data-glean-id=\"outputs\">\n      <div class=\"result-hero\">\n        <div class=\"out-label\">Network &amp; Infrastructure entitlements\n          <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">Weighted network + infrastructure entitlements \u2014 the primary SWO SaaS sizing metric. Per-module quantities are broken out below.</span></span>\n        </div>\n        <div class=\"metric\" id=\"sw-o-total\">\u2014</div>\n        <span class=\"badge\">Quantity estimate \u00b7 confirm in CPQ</span>\n      </div>\n      <div class=\"grid-out\">\n        <div class=\"out-card\">\n          <div class=\"out-label\">Network &amp; Infrastructure\n            <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">Weighted entitlements: network devices + APs\u00f710; hosts + hypervisors + VMs\u00f73 + cloud\u00f73 + containers\u00f710 + storage.</span></span>\n          </div>\n          <div class=\"out-value\" id=\"sw-o-nico\">\u2014</div>\n          <div class=\"note\" id=\"sw-o-nico-note\"></div>\n        </div>\n        <div class=\"out-card\">\n          <div class=\"out-label\">Applications &amp; Databases</div>\n          <div class=\"out-value\" id=\"sw-o-appdb\">\u2014</div>\n          <div class=\"note\" id=\"sw-o-appdb-note\"></div>\n        </div>\n        <div class=\"out-card\">\n          <div class=\"out-label\">Digital Experience</div>\n          <div class=\"out-value\" id=\"sw-o-dem\">\u2014</div>\n          <div class=\"note\" id=\"sw-o-dem-note\"></div>\n        </div>\n        <div class=\"out-card\">\n          <div class=\"out-label\">Logs</div>\n          <div class=\"out-value\" id=\"sw-o-logs\">\u2014</div>\n          <div class=\"note\" id=\"sw-o-logs-note\"></div>\n        </div>\n      </div>\n      <div id=\"sw-o-flags\"></div>\n      <p class=\"sub-head contact-head\">Contact us</p>\n      <div class=\"contact-strip\">\n        <div class=\"contact-card\">\n          <span class=\"c-role\">Product Manager</span>\n          <span class=\"c-name\">Vera Pratiwi</span>\n          <a href=\"mailto:Vera.Pratiwi@westcon.com\">Vera.Pratiwi@westcon.com</a>\n        </div>\n        <div class=\"contact-card\">\n          <span class=\"c-role\">Sales Engineer</span>\n          <span class=\"c-name\">Teguh P. Mulyo</span>\n          <a href=\"mailto:teguh.mulyo@westcon.com\">teguh.mulyo@westcon.com</a>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- LICENSE SUMMARY -->\n  <div class=\"block\" data-glean-id=\"license-summary\">\n    <p class=\"section-tag\">Licensing</p>\n    <h2>Module license summary</h2>\n    <p class=\"note\">Licensable quantities for active modules only. Confirm all quantities in CPQ.</p>\n    <table>\n      <thead><tr><th>Module</th><th>Unit of measure</th><th>Quantity</th></tr></thead>\n      <tbody id=\"sw-lic-body\"></tbody>\n    </table>\n  </div>\n\n  <!-- COLLECTOR / AGENT SIZING -->\n  <div class=\"block\" data-glean-id=\"hardware\">\n    <p class=\"section-tag\">Customer-side sizing</p>\n    <h2>Collectors &amp; agents \u2014 Minimum vs Recommended</h2>\n    <p class=\"note\" id=\"sw-hw-summary\"></p>\n    <div class=\"hw-grid\">\n      <div class=\"hw-card\">\n        <h3>1 \u00b7 Minimum</h3>\n        <p class=\"cap\">Documented minimum collector spec</p>\n        <table><thead><tr><th>Component</th><th>Qty</th><th>CPU</th><th>RAM</th><th>Storage</th></tr></thead><tbody id=\"sw-hw-min\"></tbody></table>\n      </div>\n      <div class=\"hw-card\">\n        <h3>2 \u00b7 Recommended</h3>\n        <p class=\"cap\">Recommended spec + HA / redundancy</p>\n        <table><thead><tr><th>Component</th><th>Qty</th><th>CPU</th><th>RAM</th><th>Storage</th></tr></thead><tbody id=\"sw-hw-rec\"></tbody></table>\n      </div>\n    </div>\n    <p class=\"note\" id=\"sw-hw-note\" style=\"margin-top:14px\"></p>\n  </div>\n\n  <!-- ENTITY WEIGHTING REFERENCE -->\n  <div class=\"block\" data-glean-id=\"ratio-ref\">\n    <p class=\"section-tag\">Reference</p>\n    <h2>Entity weighting &amp; units of measure</h2>\n    <table>\n      <thead><tr><th>Module</th><th>Entity / unit</th><th>Counts as</th></tr></thead>\n      <tbody>\n        <tr><td>Network</td><td>Network device (router/switch/firewall)</td><td>1:1</td></tr>\n        <tr><td>Network</td><td>Wireless access point</td><td>10:1</td></tr>\n        <tr><td>Infrastructure</td><td>Host / server (agent or collector)</td><td>1:1</td></tr>\n        <tr><td>Infrastructure</td><td>Hypervisor / virtual host</td><td>1:1</td></tr>\n        <tr><td>Infrastructure</td><td>Standalone VM</td><td>3:1</td></tr>\n        <tr><td>Infrastructure</td><td>Cloud service (AWS/Azure, non-host)</td><td>3:1</td></tr>\n        <tr><td>Infrastructure</td><td>Kubernetes container</td><td>10:1</td></tr>\n        <tr><td>Infrastructure</td><td>Storage array</td><td>1:1</td></tr>\n        <tr><td>Infrastructure</td><td>ICMP-only status node</td><td>Free</td></tr>\n        <tr><td>APM</td><td>Application service (any # instances)</td><td>Per service</td></tr>\n        <tr><td>Database</td><td>Database instance</td><td>Per instance</td></tr>\n        <tr><td>DEM \u2014 Synthetic Uptime</td><td>Uptime check = endpoint \u00d7 location \u00d7 protocol</td><td>10 uptime checks / bundle</td></tr>\n        <tr><td>DEM \u2014 Synthetic Transactions</td><td>Scripted transaction (5 checks each)</td><td>2 transactions / bundle</td></tr>\n        <tr><td>DEM \u2014 RUM</td><td>Pageviews</td><td>Per 100,000 / month</td></tr>\n        <tr><td>Logs</td><td>Log ingestion</td><td>Per GB (monthly plan)</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- ASSUMPTIONS -->\n  <div class=\"block assump\" data-glean-id=\"assumptions\">\n    <h2>How this is calculated</h2>\n    <ul>\n      <li>SolarWinds Observability SaaS uses an \u00e0-la-carte, modular subscription: each capability area is licensed independently by active entities or consumption measured in the previous calendar day.</li>\n      <li><strong>Network &amp; Infrastructure (NICO)</strong> is priced by active network devices and infrastructure hosts. Weighting: network device / hypervisor / host / storage array 1:1; wireless AP &amp; container 10:1; standalone VM &amp; cloud service 3:1. When one device is monitored via multiple channels it counts once; ICMP-only status nodes are free.</li>\n      <li><strong>APM</strong> is per active service (independent of the number of running instances). <strong>Database</strong> is per active instance. <strong>RUM</strong> is per 100,000 pageviews/month. <strong>Synthetics</strong> is licensed in bundles of 10 checks \u2014 a bundle holds either 10 uptime checks or 2 scripted transactions. <strong>Uptime checks are derived as endpoints \u00d7 locations \u00d7 protocols</strong> (e.g. 20 endpoints \u00d7 2 locations \u00d7 1 protocol = 40 uptime checks); when private probes are used, each private probe adds to the location count before multiplying. <strong>Logs</strong> is a monthly plan measured per GB ingested.</li>\n      <li><strong>No customer backend to size</strong> \u2014 storage, processing, and the web application are hosted by SolarWinds. Customer-side sizing covers only collectors and agents: the Network Collector (\u22647,000 standard devices each; min 4 CPU/16 GB, rec 8 CPU/32 GB, 40 GB + SQL), the lightweight per-host SolarWinds Observability Agent (OTLP 443, no central server), the SWO K8s Collector for clusters, and optional dedicated flow collectors (\u226440,000 flows/sec each). APM libraries and RUM run in-app; synthetics use SolarWinds public probes (or optional agent-based private probes).</li>\n    </ul>\n    <details>\n      <summary>Sources</summary>\n      <ul style=\"margin-top:12px\">\n        <li><a href=\"https://documentation.solarwinds.com/en/success_center/observability/content/settings/subscription.htm\">SWO SaaS Subscription &amp; usage calculation</a> \u2014 per-module metering and entity weighting ratios.</li>\n        <li><a href=\"https://documentation.solarwinds.com/en/success_center/observability/content/system_requirements/network_requirements.htm\">Network monitoring system requirements</a> \u2014 Network Collector CPU/RAM/storage and 7,000-device scalability.</li>\n        <li><a href=\"https://documentation.solarwinds.com/en/success_center/observability/content/system_requirements/host_requirements.htm\">Self-managed host requirements</a> \u2014 per-host SolarWinds Observability Agent.</li>\n        <li><a href=\"https://documentation.solarwinds.com/en/success_center/observability/content/configure/install-network-collector.htm\">Network Collector</a> \u2014 deploy multiple collectors; dedicated collector for heavy flow.</li>\n      </ul>\n    </details>\n  </div>\n\n  <p class=\"foot-note\">Indicative SE quantity-sizing estimate for SolarWinds Observability SaaS. Entity weighting, module tiering, and collector counts must be validated in CPQ and against current SolarWinds Observability SaaS system-requirements and subscription documentation before quoting.</p>\n</div>\n</section>\n\n<section class=\"tab-panel\" id=\"panel-ea\">\n<div class=\"shell\">\n  <p class=\"eyebrow\">SolarWinds \u00b7 Solutions Engineering \u00b7 APJ</p>\n  <h1 data-glean-id=\"title\">OSH Essentials &amp; Advanced<br>License &amp; Hardware Sizing Calculator</h1>\n  <p class=\"sub\" data-glean-id=\"intro\">Size the SolarWinds Observability Self-Hosted (OSH) <strong>Essentials</strong> or <strong>Advanced</strong> tier from monitored node capacity, then derive minimum and recommended self-hosted hardware. Both tiers use simple node-based licensing and scale through Standard and Enterprise editions. Poller sizing follows the 2026 scalability guide \u2014 per-poller capacity is protocol-dependent, not a flat element count.</p>\n\n  <div class=\"layout\">\n    <!-- INPUTS -->\n    <div class=\"panel\" data-glean-id=\"inputs\">\n      <p class=\"panel-title\">Licensing inputs</p>\n\n      <div class=\"field\" data-glean-id=\"in-tier\">\n        <label class=\"field-label\">License tier</label>\n        <p class=\"field-hint\">Essentials: NPM, SAM, LA, IPAM, UDT, VNQM &amp; Cloud. Advanced adds NTA, NCM, VMAN, SCM, anomaly-based alerting &amp; the security vulnerability dashboard.</p>\n        <div class=\"seg\" id=\"ea-seg-tier\"><button data-t=\"essentials\">Essentials</button><button data-t=\"advanced\" class=\"active\">Advanced</button></div>\n      </div>\n\n      <div class=\"explainer\" data-glean-id=\"how-counting\">\n        <strong>How licensing counts nodes:</strong> most monitored devices consume one node license each. ICMP-only status nodes (ping availability) are free, and cloud/hypervisor-discovered VMs are free until you assign additional monitoring \u2014 then each counts as one full node. Value-based fractional licensing is a Premier-only feature and does not apply to Essentials or Advanced.\n      </div>\n      <div class=\"field\" data-glean-id=\"in-nodes\">\n        <label class=\"field-label\" for=\"ea-i-nodes\">Licensed nodes (1 each)</label>\n        <p class=\"field-hint\">Servers, network devices, wireless controllers, autonomous APs, and any node with monitoring beyond ICMP status. Exclude ICMP-only status nodes (free).</p>\n        <input type=\"number\" id=\"ea-i-nodes\" min=\"0\" value=\"820\">\n      </div>\n      <div class=\"row2\">\n        <div class=\"field\" data-glean-id=\"in-add\"><label class=\"field-label\" for=\"ea-i-add\">Planned additions</label><input type=\"number\" id=\"ea-i-add\" min=\"0\" value=\"110\"></div>\n        <div class=\"field\" data-glean-id=\"in-headroom\"><label class=\"field-label\" for=\"ea-i-headroom\">Growth headroom %</label><input type=\"number\" id=\"ea-i-headroom\" min=\"0\" max=\"200\" value=\"8\"></div>\n      </div>\n      <div class=\"field\" data-glean-id=\"in-edition\">\n        <label class=\"field-label\">Scale edition</label>\n        <p class=\"field-hint\">Standard scales up to 1,500 nodes. Enterprise is required beyond 1,500 nodes and whenever Additional Polling Engines (APEs) are needed.</p>\n        <div class=\"seg\" id=\"ea-seg-edition\"><button data-ed=\"auto\" class=\"active\">Auto</button><button data-ed=\"standard\">Standard</button><button data-ed=\"enterprise\">Enterprise</button></div>\n      </div>\n\n      <p class=\"sub-head\" data-glean-id=\"hw-osh-head\">Self-Hosted (OSH) polling workload</p>\n      <div class=\"field\" data-glean-id=\"in-proto\">\n        <label class=\"field-label\">Primary polling protocol</label>\n        <p class=\"field-hint\">Sets per-poller element capacity: SNMPv2 100k \u00b7 SNMPv3 72k \u00b7 WMI/WinRM 20k (max 2,000 nodes), at 16 cores.</p>\n        <div class=\"seg\" id=\"ea-seg-proto\"><button data-p=\"snmpv2\" class=\"active\">SNMPv2</button><button data-p=\"snmpv3\">SNMPv3</button><button data-p=\"wmi\">WMI/WinRM</button></div>\n      </div>\n      <div class=\"field\" data-glean-id=\"in-epn\">\n        <label class=\"field-label\" for=\"ea-i-epn\">Avg monitored elements per node</label>\n        <p class=\"field-hint\">Interfaces, volumes, apps, component monitors per node. Typical 8\u201312.</p>\n        <input type=\"number\" id=\"ea-i-epn\" min=\"1\" value=\"10\">\n      </div>\n      <div class=\"row2\">\n        <div class=\"field\" data-glean-id=\"in-components\"><label class=\"field-label\" for=\"ea-i-components\">SAM component monitors</label><p class=\"field-hint\">40k / APE.</p><input type=\"number\" id=\"ea-i-components\" min=\"0\" value=\"0\"></div>\n        <div class=\"field\" data-glean-id=\"in-agents\"><label class=\"field-label\" for=\"ea-i-agents\">SolarWinds agents</label><p class=\"field-hint\">1,000 / poller.</p><input type=\"number\" id=\"ea-i-agents\" min=\"0\" value=\"0\"></div>\n      </div>\n      <div class=\"row2\">\n        <div class=\"field\" data-glean-id=\"in-fps\"><label class=\"field-label\" for=\"ea-i-fps\">NetFlow flows/sec (on-prem)</label><p class=\"field-hint\">50k FPS / poller. Requires Advanced (NTA).</p><input type=\"number\" id=\"ea-i-fps\" min=\"0\" value=\"0\"></div>\n        <div class=\"field\" data-glean-id=\"in-webusers\"><label class=\"field-label\" for=\"ea-i-webusers\">Concurrent web users</label><p class=\"field-hint\">25\u201350 / web server.</p><input type=\"number\" id=\"ea-i-webusers\" min=\"0\" value=\"25\"></div>\n      </div>\n    </div>\n\n    <!-- OUTPUTS -->\n    <div data-glean-id=\"outputs\">\n      <div class=\"result-hero\" data-glean-id=\"hero\">\n        <div class=\"out-label\">Recommended license tier\n          <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">Smallest published node tier covering total required capacity for the selected OSH tier. CPQ rounds up to the next valid tier.</span></span>\n        </div>\n        <div class=\"metric\" id=\"ea-o-tier\">\u2014</div>\n        <span class=\"badge\" id=\"ea-o-tiername\">\u2014</span>\n      </div>\n      <div class=\"grid-out\">\n        <div class=\"out-card\" data-glean-id=\"o-capacity-card\">\n          <div class=\"out-label\">Total required capacity\n            <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">Licensed nodes + planned additions, then + growth headroom %.</span></span>\n          </div>\n          <div class=\"out-value\" id=\"ea-o-capacity\">\u2014</div>\n          <div class=\"note\" id=\"ea-o-capacity-break\"></div>\n        </div>\n        <div class=\"out-card\" data-glean-id=\"o-edition-card\">\n          <div class=\"out-label\">Scale edition\n            <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">Standard up to 1,500 nodes (includes additional web servers; HA is an add-on). Enterprise required above 1,500 nodes or for APEs; adds APEs, HA, EOC, lab licenses &amp; Advanced Support.</span></span>\n          </div>\n          <div class=\"out-value\" id=\"ea-o-edition\">\u2014</div>\n          <div class=\"note\" id=\"ea-o-edition-note\"></div>\n        </div>\n        <div class=\"out-card\" data-glean-id=\"o-pollers-card\">\n          <div class=\"out-label\">Polling engines required\n            <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">Maximum across workload dimensions: elements \u00f7 protocol capacity, SAM components \u00f7 40k, flows \u00f7 50k FPS, agents \u00f7 1,000, and WMI's 2,000-node cap. APEs require an Enterprise license.</span></span>\n          </div>\n          <div class=\"out-value\" id=\"ea-o-pollers\">\u2014</div>\n          <div class=\"note\" id=\"ea-o-pollers-note\"></div>\n        </div>\n        <div class=\"out-card\" data-glean-id=\"o-web-card\">\n          <div class=\"out-label\">Additional web servers\n            <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">The main server hosts the Web Console for up to ~50 concurrent users; add web servers for more. Included in both Standard and Enterprise.</span></span>\n          </div>\n          <div class=\"out-value\" id=\"ea-o-web\">\u2014</div>\n          <div class=\"note\" id=\"ea-o-web-note\"></div>\n        </div>\n      </div>\n      <div id=\"ea-o-flags\"></div>\n      <p class=\"sub-head contact-head\">Contact us</p>\n      <div class=\"contact-strip\">\n        <div class=\"contact-card\">\n          <span class=\"c-role\">Product Manager</span>\n          <span class=\"c-name\">Vera Pratiwi</span>\n          <a href=\"mailto:Vera.Pratiwi@westcon.com\">Vera.Pratiwi@westcon.com</a>\n        </div>\n        <div class=\"contact-card\">\n          <span class=\"c-role\">Sales Engineer</span>\n          <span class=\"c-name\">Teguh P. Mulyo</span>\n          <a href=\"mailto:teguh.mulyo@westcon.com\">teguh.mulyo@westcon.com</a>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- MODULE COVERAGE -->\n  <div class=\"block\" data-glean-id=\"module-table\">\n    <p class=\"section-tag\">Reference</p>\n    <h2>Module coverage by tier</h2>\n    <p class=\"note\">Selected tier highlighted. Advanced includes everything in Essentials plus the additional capabilities below.</p>\n    <table>\n      <thead><tr><th>Capability</th><th id=\"ea-th-ess\">Essentials</th><th id=\"ea-th-adv\">Advanced</th></tr></thead>\n      <tbody id=\"ea-module-body\"></tbody>\n    </table>\n    <p class=\"note\" style=\"margin-top:12px\">Additional Polling Engines (APEs), Enterprise Operations Console (EOC), and lab licenses require the <strong>Enterprise</strong> edition of either tier. High Availability is available as an add-on on Standard.</p>\n  </div>\n\n  <!-- TIER TABLE -->\n  <div class=\"block\" data-glean-id=\"tier-table\">\n    <p class=\"section-tag\">Reference</p>\n    <h2>Published node tiers</h2>\n    <p class=\"note\">Matching tier highlighted. Standard up to 1,500 nodes; Enterprise from 500 and required beyond 1,500.</p>\n    <table>\n      <thead><tr><th>Edition</th><th>Available node tiers</th></tr></thead>\n      <tbody>\n        <tr id=\"ea-tr-standard\"><td>Standard</td><td id=\"ea-tiers-standard\"></td></tr>\n        <tr id=\"ea-tr-enterprise\"><td>Enterprise</td><td id=\"ea-tiers-enterprise\"></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- HARDWARE -->\n  <div class=\"block\" data-glean-id=\"hardware\">\n    <p class=\"section-tag\">Hardware sizing</p>\n    <h2>Self-Hosted infrastructure \u2014 Minimum vs Recommended</h2>\n    <p class=\"note\" id=\"ea-hw-summary\"></p>\n    <div class=\"hw-grid\">\n      <div class=\"hw-card\" data-glean-id=\"hw-min\">\n        <h3>1 \u00b7 Minimum hardware</h3>\n        <p class=\"cap\" id=\"ea-hw-min-cap\"></p>\n        <div class=\"grp\">Self-Hosted (OSH)</div>\n        <table><thead><tr><th>Component</th><th>Qty</th><th>CPU</th><th>RAM</th><th>Storage</th></tr></thead><tbody id=\"ea-hw-min-osh\"></tbody></table>\n      </div>\n      <div class=\"hw-card\" data-glean-id=\"hw-rec\">\n        <h3>2 \u00b7 Recommended hardware</h3>\n        <p class=\"cap\" id=\"ea-hw-rec-cap\"></p>\n        <div class=\"grp\">Self-Hosted (OSH)</div>\n        <table><thead><tr><th>Component</th><th>Qty</th><th>CPU</th><th>RAM</th><th>Storage</th></tr></thead><tbody id=\"ea-hw-rec-osh\"></tbody></table>\n      </div>\n    </div>\n    <p class=\"note\" id=\"ea-hw-poller-note\" style=\"margin-top:14px\"></p>\n  </div>\n\n  <!-- SCALABILITY REFERENCE -->\n  <div class=\"block\" data-glean-id=\"scal-ref\">\n    <p class=\"section-tag\">Reference</p>\n    <h2>Per-poller scalability limits (2026 guide)</h2>\n    <table>\n      <thead><tr><th>Dimension</th><th>Per polling engine</th><th>Per instance</th></tr></thead>\n      <tbody>\n        <tr><td>Elements \u2014 SNMPv2</td><td>100,000 (16 cores; +7,500/core \u2192 max 150,000)</td><td rowspan=\"3\">1,000,000 elements \u00b7 100 APEs</td></tr>\n        <tr><td>Elements \u2014 SNMPv3</td><td>72,000 (16 cores; +5,000/core \u2192 max 100,000)</td></tr>\n        <tr><td>Elements \u2014 WMI/WinRM</td><td>20,000 (max 2,000 nodes; +2,000/core \u2192 30,000)</td></tr>\n        <tr><td>SAM component monitors</td><td>40,000 (APE) \u00b7 ~10,000 (main)</td><td>550,000</td></tr>\n        <tr><td>NetFlow (NTA) \u2014 Advanced</td><td>50,000 flows/sec</td><td>300,000 flows/sec</td></tr>\n        <tr><td>SolarWinds agents</td><td>1,000 (\u221210 per remote collector)</td><td>\u2014</td></tr>\n        <tr><td>UDT ports</td><td>100,000</td><td>500,000</td></tr>\n        <tr><td>VMAN VMs \u2014 Advanced</td><td>10,000 (per APE)</td><td>\u2014</td></tr>\n        <tr><td>Web console users</td><td>25\u201350 per web server</td><td>50\u2013100 (main)</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- ASSUMPTIONS -->\n  <div class=\"block assump\" data-glean-id=\"assumptions\">\n    <h2>How this is calculated</h2>\n    <ul>\n      <li>OSH Essentials and Advanced use simple node-based tier licensing. ICMP-only availability nodes are free; a node becomes billable once additional monitoring (apps, interfaces, NCM profiles, or other services) is enabled. Cloud/hypervisor-discovered VMs are free until additional monitoring is assigned, then count as one full node.</li>\n      <li><strong>Essentials</strong> includes NPM, SAM, LA, IPAM, UDT, VNQM and cloud monitoring. <strong>Advanced</strong> adds flow monitoring (NTA), NCM, VMAN, SCM, ML anomaly-based alerting, and the security vulnerability dashboard. WPM, SRM, Incident Response and the attached SWO SaaS (NICO) license are Premier-only and are not included here.</li>\n      <li>Value-based (fractional) licensing and license overages/bursting are Premier-only features and are excluded from this Essentials/Advanced sizing.</li>\n      <li><strong>Scale edition:</strong> Standard includes additional web servers and allows HA as an add-on but does not include APEs. If sizing needs one or more APEs, or capacity exceeds 1,500 nodes, an <strong>Enterprise</strong> license is required. Enterprise also bundles HA, EOC, lab licenses and Advanced Support.</li>\n      <li><strong>Polling engine count</strong> is the maximum across workload dimensions: elements \u00f7 protocol capacity (SNMPv2 100k / SNMPv3 72k / WMI 20k, at 16 cores), SAM components \u00f7 40,000, flows \u00f7 50,000 FPS (Advanced only), agents \u00f7 1,000, and WMI's 2,000-node cap. Each instance supports up to 100 APEs and 1,000,000 elements.</li>\n      <li>Server hardware tiers (CPU/RAM) follow SolarWinds Platform 2026.2 system requirements; element-heavy pollers need 16 cores to reach the protocol caps, and more cores raise the cap further. Recommended adds a headroom tier plus redundancy: an HA database pair, an extra APE, and an additional web server.</li>\n    </ul>\n    <details>\n      <summary>Sources</summary>\n      <ul style=\"margin-top:12px\">\n        <li><a href=\"https://documentation.solarwinds.com/en/success_center/orionplatform/content/orion_platform_licensing_model.htm\">OSH licensing model</a> \u2014 Essentials/Advanced tiers, Standard vs Enterprise editions, ICMP-free nodes, APE requirement.</li>\n        <li><a href=\"https://documentation.solarwinds.com/en/success_center/orionplatform/content/orion_platform_scalability_engine_guidelines.htm\">Scalability engine guidelines (2026)</a> \u2014 per-poller SNMPv2/v3/WMI, SAM, flows, agents, per-instance limits.</li>\n        <li><a href=\"https://documentation.solarwinds.com/en/success_center/orionplatform/content/system_requirements/solarwinds_platform_2026-2_system_requirements.htm\">SolarWinds Platform 2026.2 system requirements</a> \u2014 server/DB/APE/web CPU-RAM specs.</li>\n      </ul>\n    </details>\n  </div>\n\n  <p class=\"foot-note\">Indicative SE sizing estimate for OSH Essentials and Advanced. Licensing, module coverage, protocol mix and final hardware must be validated in CPQ and against the customer's live license report and current 2026 system-requirements / scalability documentation before quoting.</p>\n</div>\n</section>\n\n<section class=\"tab-panel\" id=\"panel-pr\">\n<div class=\"shell\">\n  <p class=\"eyebrow\">SolarWinds \u00b7 Solutions Engineering \u00b7 APJ</p>\n  <h1 data-glean-id=\"title\">OSH Premier<br>License &amp; Hardware Sizing Calculator</h1>\n  <p class=\"sub\" data-glean-id=\"intro\">Size the SolarWinds Observability Self-Hosted (OSH) Premier tier from monitored capacity, then derive minimum and recommended hardware for the self-hosted platform and the SaaS side (network collectors and per-host agents). Poller sizing follows the 2026 scalability guide \u2014 per-poller capacity is protocol-dependent, not a flat element count.</p>\n\n  <div class=\"layout\">\n    <!-- INPUTS -->\n    <div class=\"panel\" data-glean-id=\"inputs\">\n      <p class=\"panel-title\">Licensing inputs</p>\n      <div class=\"explainer\" data-glean-id=\"how-counting\">\n        <strong>How licensing counts things:</strong> most devices use 1 full license each. Smaller resources share a license \u2014 cloud VMs 3-to-1, containers &amp; thin wireless APs 10-to-1. Enter each type in its own field; sharing is applied automatically.\n      </div>\n      <div class=\"field\" data-glean-id=\"in-nodes\">\n        <label class=\"field-label\" for=\"pr-i-nodes\">Full-license nodes (1 each)</label>\n        <p class=\"field-hint\">Servers, network devices, wireless controllers, autonomous APs, paid ICMP nodes. Exclude ICMP-only status nodes (free).</p>\n        <input type=\"number\" id=\"pr-i-nodes\" min=\"0\" value=\"820\">\n      </div>\n      <div class=\"field\" data-glean-id=\"in-cloud\">\n        <label class=\"field-label\" for=\"pr-i-cloud\">Cloud VMs / small cloud resources</label>\n        <p class=\"field-hint\">3 share 1 node.</p>\n        <input type=\"number\" id=\"pr-i-cloud\" min=\"0\" value=\"0\">\n      </div>\n      <div class=\"row2\">\n        <div class=\"field\" data-glean-id=\"in-containers\">\n          <label class=\"field-label\" for=\"pr-i-containers\">Containers / K8s</label>\n          <p class=\"field-hint\">10 share 1 node.</p>\n          <input type=\"number\" id=\"pr-i-containers\" min=\"0\" value=\"0\">\n        </div>\n        <div class=\"field\" data-glean-id=\"in-thinap\">\n          <label class=\"field-label\" for=\"pr-i-thinap\">Thin APs</label>\n          <p class=\"field-hint\">10 share 1 node.</p>\n          <input type=\"number\" id=\"pr-i-thinap\" min=\"0\" value=\"0\">\n        </div>\n      </div>\n      <div class=\"row2\">\n        <div class=\"field\" data-glean-id=\"in-add\"><label class=\"field-label\" for=\"pr-i-add\">Planned additions</label><input type=\"number\" id=\"pr-i-add\" min=\"0\" value=\"110\"></div>\n        <div class=\"field\" data-glean-id=\"in-headroom\"><label class=\"field-label\" for=\"pr-i-headroom\">Growth headroom %</label><input type=\"number\" id=\"pr-i-headroom\" min=\"0\" max=\"200\" value=\"8\"></div>\n      </div>\n      <div class=\"field\" data-glean-id=\"in-edition\">\n        <label class=\"field-label\">Edition</label>\n        <div class=\"seg\" id=\"pr-seg-edition\"><button data-ed=\"auto\" class=\"active\">Auto</button><button data-ed=\"standard\">Standard</button><button data-ed=\"enterprise\">Enterprise</button></div>\n      </div>\n      <div class=\"field\" data-glean-id=\"in-overage\">\n        <label class=\"field-label\">Overage / bursting?</label>\n        <div class=\"seg\" id=\"pr-seg-overage\"><button data-ov=\"no\" class=\"active\">No</button><button data-ov=\"yes\">Yes</button></div>\n      </div>\n\n      <p class=\"sub-head\" data-glean-id=\"tier2-head\">Included components (Tier 2 \u00b7 no node impact in 2026.2)</p>\n      <div class=\"row2\">\n        <div class=\"field\" data-glean-id=\"in-arrays\"><label class=\"field-label\" for=\"pr-i-arrays\">Storage arrays (SRM)</label><input type=\"number\" id=\"pr-i-arrays\" min=\"0\" value=\"0\"></div>\n        <div class=\"field\" data-glean-id=\"in-wpm\"><label class=\"field-label\" for=\"pr-i-wpm\">WPM transactions</label><input type=\"number\" id=\"pr-i-wpm\" min=\"0\" value=\"0\"></div>\n      </div>\n      <div class=\"field\" data-glean-id=\"in-ir\"><label class=\"field-label\" for=\"pr-i-ir\">Incident Response users</label><input type=\"number\" id=\"pr-i-ir\" min=\"0\" value=\"0\"></div>\n\n      <p class=\"sub-head\" data-glean-id=\"hw-osh-head\">Self-Hosted (OSH) polling workload</p>\n      <div class=\"field\" data-glean-id=\"in-proto\">\n        <label class=\"field-label\">Primary polling protocol</label>\n        <p class=\"field-hint\">Sets per-poller element capacity: SNMPv2 100k \u00b7 SNMPv3 72k \u00b7 WMI/WinRM 20k (max 2,000 nodes), at 16 cores.</p>\n        <div class=\"seg\" id=\"pr-seg-proto\"><button data-p=\"snmpv2\" class=\"active\">SNMPv2</button><button data-p=\"snmpv3\">SNMPv3</button><button data-p=\"wmi\">WMI/WinRM</button></div>\n      </div>\n      <div class=\"field\" data-glean-id=\"in-epn\">\n        <label class=\"field-label\" for=\"pr-i-epn\">Avg monitored elements per node</label>\n        <p class=\"field-hint\">Interfaces, volumes, apps, component monitors per node. Typical 8\u201312.</p>\n        <input type=\"number\" id=\"pr-i-epn\" min=\"1\" value=\"10\">\n      </div>\n      <div class=\"row2\">\n        <div class=\"field\" data-glean-id=\"in-components\"><label class=\"field-label\" for=\"pr-i-components\">SAM component monitors</label><p class=\"field-hint\">40k / APE.</p><input type=\"number\" id=\"pr-i-components\" min=\"0\" value=\"0\"></div>\n        <div class=\"field\" data-glean-id=\"in-agents\"><label class=\"field-label\" for=\"pr-i-agents\">SolarWinds agents</label><p class=\"field-hint\">1,000 / poller.</p><input type=\"number\" id=\"pr-i-agents\" min=\"0\" value=\"0\"></div>\n      </div>\n      <div class=\"row2\">\n        <div class=\"field\" data-glean-id=\"in-fps\"><label class=\"field-label\" for=\"pr-i-fps\">NetFlow flows/sec (on-prem)</label><p class=\"field-hint\">50k FPS / poller.</p><input type=\"number\" id=\"pr-i-fps\" min=\"0\" value=\"0\"></div>\n        <div class=\"field\" data-glean-id=\"in-webusers\"><label class=\"field-label\" for=\"pr-i-webusers\">Concurrent web users</label><p class=\"field-hint\">25\u201350 / web server.</p><input type=\"number\" id=\"pr-i-webusers\" min=\"0\" value=\"25\"></div>\n      </div>\n\n      <p class=\"sub-head\" data-glean-id=\"hw-saas-head\">SaaS monitoring scope</p>\n      <div class=\"field\" data-glean-id=\"in-saasdev\">\n        <label class=\"field-label\" for=\"pr-i-saasdev\">SaaS network devices (collector)</label>\n        <p class=\"field-hint\">Agentless via Network Collector \u2014 up to 7,000 standard devices each.</p>\n        <input type=\"number\" id=\"pr-i-saasdev\" min=\"0\" value=\"0\">\n      </div>\n      <div class=\"row2\">\n        <div class=\"field\" data-glean-id=\"in-saasagent\"><label class=\"field-label\" for=\"pr-i-saasagent\">SaaS servers \u2014 Agent</label><p class=\"field-hint\">Per-host agent.</p><input type=\"number\" id=\"pr-i-saasagent\" min=\"0\" value=\"0\"></div>\n        <div class=\"field\" data-glean-id=\"in-saasagentless\"><label class=\"field-label\" for=\"pr-i-saasagentless\">SaaS servers \u2014 agentless</label><p class=\"field-hint\">Via collector.</p><input type=\"number\" id=\"pr-i-saasagentless\" min=\"0\" value=\"0\"></div>\n      </div>\n      <div class=\"field\" data-glean-id=\"in-flows\"><label class=\"field-label\" for=\"pr-i-flows\">SaaS flows/sec</label><p class=\"field-hint\">\u226440,000 flows/sec per collector.</p><input type=\"number\" id=\"pr-i-flows\" min=\"0\" value=\"0\"></div>\n    </div>\n\n    <!-- OUTPUTS -->\n    <div data-glean-id=\"outputs\">\n      <div class=\"result-hero\" data-glean-id=\"hero\">\n        <div class=\"out-label\">Recommended Premier tier\n          <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">Smallest published Premier node tier covering total required capacity. CPQ rounds up to the next valid tier.</span></span>\n        </div>\n        <div class=\"metric\" id=\"pr-o-tier\">\u2014</div>\n        <span class=\"badge\" id=\"pr-o-edition\">\u2014</span>\n      </div>\n      <div class=\"grid-out\">\n        <div class=\"out-card\" data-glean-id=\"o-capacity-card\">\n          <div class=\"out-label\">Total required capacity\n            <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">Full nodes + additions + cloud (\u00f73) + containers (\u00f710) + thin APs (\u00f710), then + growth headroom %.</span></span>\n          </div>\n          <div class=\"out-value\" id=\"pr-o-capacity\">\u2014</div>\n          <div class=\"note\" id=\"pr-o-capacity-break\"></div>\n        </div>\n        <div class=\"out-card\" data-glean-id=\"o-saas-card\">\n          <div class=\"out-label\">Attached SaaS capacity\n            <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">SWO SaaS (NICO) network/infra quantity aligns 1:1 with the Premier quantity.</span></span>\n          </div>\n          <div class=\"out-value\" id=\"pr-o-saas\">\u2014</div>\n          <div class=\"note\">Aligned 1:1 with Premier nodes</div>\n        </div>\n        <div class=\"out-card\" data-glean-id=\"o-overage-card\">\n          <div class=\"out-label\">Overage headroom\n            <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">Adds 25% of the license or 500 nodes, whichever first. Requires SWIP + outbound connectivity.</span></span>\n          </div>\n          <div class=\"out-value\" id=\"pr-o-overage\">\u2014</div>\n          <div class=\"note\" id=\"pr-o-overage-note\">Enable overage to calculate burst</div>\n        </div>\n        <div class=\"out-card\" data-glean-id=\"o-srm-card\">\n          <div class=\"out-label\">Storage / WPM (included)\n            <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">WPM &amp; SRM are included &amp; unlimited in Premier today (Silicon 2026.2) and do not consume nodes. From Tungsten 2026.4, SRM is planned at ~5 nodes/array.</span></span>\n          </div>\n          <div class=\"out-value\" id=\"pr-o-srm\">Included</div>\n          <div class=\"note\" id=\"pr-o-srm-note\"></div>\n        </div>\n        <div class=\"out-card\" data-glean-id=\"o-ir-card\">\n          <div class=\"out-label\">Incident Response\n            <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">IR Pro is bundled; included user count is set by the Premier tier. Extra users add independently at cost.</span></span>\n          </div>\n          <div class=\"out-value\" id=\"pr-o-ir\">Bundled</div>\n          <div class=\"note\" id=\"pr-o-ir-note\"></div>\n        </div>\n      </div>\n      <div id=\"pr-o-flags\"></div>\n      <p class=\"sub-head contact-head\">Contact us</p>\n      <div class=\"contact-strip\">\n        <div class=\"contact-card\">\n          <span class=\"c-role\">Product Manager</span>\n          <span class=\"c-name\">Vera Pratiwi</span>\n          <a href=\"mailto:Vera.Pratiwi@westcon.com\">Vera.Pratiwi@westcon.com</a>\n        </div>\n        <div class=\"contact-card\">\n          <span class=\"c-role\">Sales Engineer</span>\n          <span class=\"c-name\">Teguh P. Mulyo</span>\n          <a href=\"mailto:teguh.mulyo@westcon.com\">teguh.mulyo@westcon.com</a>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- TIER TABLE -->\n  <div class=\"block\" data-glean-id=\"tier-table\">\n    <p class=\"section-tag\">Reference</p>\n    <h2>Published Premier node tiers</h2>\n    <p class=\"note\">Matching tier highlighted. Standard up to 1,500 nodes; Enterprise from 500 and required beyond 1,500.</p>\n    <table>\n      <thead><tr><th>Edition</th><th>Available node tiers</th></tr></thead>\n      <tbody>\n        <tr id=\"pr-tr-standard\"><td>Standard</td><td id=\"pr-tiers-standard\"></td></tr>\n        <tr id=\"pr-tr-enterprise\"><td>Enterprise</td><td id=\"pr-tiers-enterprise\"></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- HARDWARE -->\n  <div class=\"block\" data-glean-id=\"hardware\">\n    <p class=\"section-tag\">Hardware sizing</p>\n    <h2>Infrastructure \u2014 Minimum vs Recommended</h2>\n    <p class=\"note\" id=\"pr-hw-summary\"></p>\n    <div class=\"hw-grid\">\n      <div class=\"hw-card\" data-glean-id=\"hw-min\">\n        <h3>1 \u00b7 Minimum hardware</h3>\n        <p class=\"cap\" id=\"pr-hw-min-cap\"></p>\n        <div class=\"grp\">Self-Hosted (OSH)</div>\n        <table><thead><tr><th>Component</th><th>Qty</th><th>CPU</th><th>RAM</th><th>Storage</th></tr></thead><tbody id=\"pr-hw-min-osh\"></tbody></table>\n        <div class=\"grp\">SaaS side</div>\n        <table><thead><tr><th>Component</th><th>Qty</th><th>CPU</th><th>RAM</th><th>Storage</th></tr></thead><tbody id=\"pr-hw-min-saas\"></tbody></table>\n      </div>\n      <div class=\"hw-card\" data-glean-id=\"hw-rec\">\n        <h3>2 \u00b7 Recommended hardware</h3>\n        <p class=\"cap\" id=\"pr-hw-rec-cap\"></p>\n        <div class=\"grp\">Self-Hosted (OSH)</div>\n        <table><thead><tr><th>Component</th><th>Qty</th><th>CPU</th><th>RAM</th><th>Storage</th></tr></thead><tbody id=\"pr-hw-rec-osh\"></tbody></table>\n        <div class=\"grp\">SaaS side</div>\n        <table><thead><tr><th>Component</th><th>Qty</th><th>CPU</th><th>RAM</th><th>Storage</th></tr></thead><tbody id=\"pr-hw-rec-saas\"></tbody></table>\n      </div>\n    </div>\n    <p class=\"note\" id=\"pr-hw-poller-note\" style=\"margin-top:14px\"></p>\n  </div>\n\n  <!-- SCALABILITY REFERENCE -->\n  <div class=\"block\" data-glean-id=\"scal-ref\">\n    <p class=\"section-tag\">Reference</p>\n    <h2>Per-poller scalability limits (2026 guide)</h2>\n    <table>\n      <thead><tr><th>Dimension</th><th>Per polling engine</th><th>Per instance</th></tr></thead>\n      <tbody>\n        <tr><td>Elements \u2014 SNMPv2</td><td>100,000 (16 cores; +7,500/core \u2192 max 150,000)</td><td rowspan=\"3\">1,000,000 elements \u00b7 100 APEs</td></tr>\n        <tr><td>Elements \u2014 SNMPv3</td><td>72,000 (16 cores; +5,000/core \u2192 max 100,000)</td></tr>\n        <tr><td>Elements \u2014 WMI/WinRM</td><td>20,000 (max 2,000 nodes; +2,000/core \u2192 30,000)</td></tr>\n        <tr><td>SAM component monitors</td><td>40,000 (APE) \u00b7 ~10,000 (main)</td><td>550,000</td></tr>\n        <tr><td>NetFlow (NTA)</td><td>50,000 flows/sec</td><td>300,000 flows/sec</td></tr>\n        <tr><td>SolarWinds agents</td><td>1,000 (\u221210 per remote collector)</td><td>\u2014</td></tr>\n        <tr><td>SRM LUNs</td><td>40,000</td><td>160,000</td></tr>\n        <tr><td>UDT ports</td><td>100,000</td><td>500,000</td></tr>\n        <tr><td>VMAN VMs</td><td>10,000 (per APE)</td><td>\u2014</td></tr>\n        <tr><td>Web console users</td><td>25\u201350 per web server</td><td>50\u2013100 (main)</td></tr>\n        <tr><td>SaaS Network Collector</td><td>7,000 standard devices \u00b7 40,000 flows/sec</td><td>deploy multiple</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- ASSUMPTIONS -->\n  <div class=\"block assump\" data-glean-id=\"assumptions\">\n    <h2>How this is calculated</h2>\n    <ul>\n      <li>Premier uses node-based tier licensing and scales like Essentials/Advanced; ICMP-only nodes are free until additional monitoring is enabled. Cloud VMs ~3:1, containers ~10:1, thin APs 10:1 (confirm against the live license report).</li>\n      <li>WPM &amp; SRM are included and unlimited in Premier today (Silicon 2026.2) and do not consume nodes; from Tungsten 2026.4, SRM is planned at ~5 nodes/array. IR Pro is bundled by tier; SaaS (NICO) aligns 1:1.</li>\n      <li><strong>OSH poller count</strong> is the maximum across workload dimensions: elements \u00f7 protocol capacity (SNMPv2 100k / SNMPv3 72k / WMI 20k, at 16 cores), SAM components \u00f7 40,000, flows \u00f7 50,000 FPS, agents \u00f7 1,000, and WMI's 2,000-node cap. Each instance supports up to 100 APEs and 1,000,000 elements.</li>\n      <li>Server hardware tiers (CPU/RAM) follow SolarWinds Platform 2026.2 system requirements; element-heavy pollers need 16 cores to reach the protocol caps, and more cores raise the cap further.</li>\n      <li><strong>SaaS network devices</strong> are sized by the Network Collector (\u22647,000 standard devices each; a standard device is SNMPv2 with ~15 interfaces). <strong>SaaS servers</strong> are monitored by the per-host Observability Agent (no central server; sends via OTLP 443) or agentlessly through a collector. Flow monitoring is \u226440,000 flows/sec per collector.</li>\n      <li>Recommended adds a headroom tier plus redundancy: HA database pair, an extra APE, an additional web server, and a standby / dedicated flow collector.</li>\n    </ul>\n    <details>\n      <summary>Sources</summary>\n      <ul style=\"margin-top:12px\">\n        <li><a href=\"https://documentation.solarwinds.com/en/success_center/orionplatform/content/orion_platform_scalability_engine_guidelines.htm\">Scalability engine guidelines (2026)</a> \u2014 per-poller SNMPv2/v3/WMI, SAM, flows, agents, per-instance limits.</li>\n        <li><a href=\"https://documentation.solarwinds.com/en/success_center/orionplatform/content/system_requirements/solarwinds_platform_2026-2_system_requirements.htm\">SolarWinds Platform 2026.2 system requirements</a> \u2014 server/DB/APE/web CPU-RAM specs.</li>\n        <li><a href=\"https://documentation.solarwinds.com/en/success_center/observability/content/configure/install-network-collector.htm\">SWO Network Collector</a> \u2014 7,000 devices/collector, flow limits.</li>\n        <li><a href=\"https://documentation.solarwinds.com/en/success_center/observability/content/system_requirements/host_requirements.htm\">SWO self-managed host requirements</a> \u2014 per-host Observability Agent for server monitoring.</li>\n        <li><a href=\"https://documentation.solarwinds.com/en/success_center/orionplatform/content/orion_platform_licensing_model.htm\">OSH licensing model</a> &amp; <a href=\"https://solarwinds.sharepoint.com/sites/RevenueEnablement/SitePages/How-to-Quote-Observability-Self-Hosted-(OSH)-Premier.aspx\">How to Quote OSH Premier</a> \u2014 tiers, editions, VBL, overages, 1:1 SaaS, IR bundling.</li>\n      </ul>\n    </details>\n  </div>\n\n  <p class=\"foot-note\">Indicative SE sizing estimate. Pricing, value-based licensing weights, protocol mix, and final hardware must be validated in CPQ and against the customer's live license report and current 2026 system-requirements / scalability documentation before quoting.</p>\n</div>\n</section>\n<section class=\"tab-panel\" id=\"panel-dpa\">\n<div class=\"shell\">\n  <p class=\"eyebrow\">SolarWinds \u00b7 Solutions Engineering \u00b7 APJ</p>\n  <h1 data-glean-id=\"title\">Database Performance Analyzer (DPA)<br>License &amp; Server Sizing Calculator</h1>\n  <p class=\"sub\" data-glean-id=\"intro\">Size a SolarWinds DPA deployment from the number of monitored database instances. DPA is licensed <strong>per monitored database instance</strong> \u2014 current subscription licenses are <strong>DBSH</strong> (Database Self-Hosted, any edition of any supported database, VM metrics included) and <strong>DBSHDS</strong> (Database Self-Hosted DBaaS). Server and repository hardware follow the DPA 2026.2 system requirements, bracketed by instances per DPA server (max 250 each).</p>\n\n  <div class=\"layout\">\n    <!-- INPUTS -->\n    <div class=\"panel\">\n      <p class=\"panel-title\">Licensing inputs</p>\n      <div class=\"explainer\">\n        <strong>How DPA licensing counts:</strong> one license per monitored database instance. DBSH covers any edition of SQL Server, Oracle, MySQL, MariaDB, PostgreSQL, Db2, SAP ASE &amp; HANA (cloud-hosted equivalents included) and bundles VM metrics \u2014 no VM Option needed. DBSHDS covers DBaaS targets such as Azure SQL Database. Licenses float: register more instances than licenses and assign them on the allocation page.\n      </div>\n      <div class=\"field\">\n        <label class=\"field-label\" for=\"dpa-i-dbsh\">Self-hosted DB instances (DBSH)</label>\n        <p class=\"field-hint\">SQL Server, Oracle, MySQL, MariaDB, PostgreSQL, Db2, SAP ASE/HANA \u2014 incl. RDS, Aurora, Cloud SQL, Azure MI. 1 license each.</p>\n        <input type=\"number\" id=\"dpa-i-dbsh\" min=\"0\" value=\"60\">\n      </div>\n      <div class=\"field\">\n        <label class=\"field-label\" for=\"dpa-i-dbshds\">DBaaS instances (DBSHDS)</label>\n        <p class=\"field-hint\">Azure SQL Database and other supported DBaaS targets. 1 license each.</p>\n        <input type=\"number\" id=\"dpa-i-dbshds\" min=\"0\" value=\"0\">\n      </div>\n      <div class=\"row2\">\n        <div class=\"field\"><label class=\"field-label\" for=\"dpa-i-add\">Planned additions</label><input type=\"number\" id=\"dpa-i-add\" min=\"0\" value=\"0\"></div>\n        <div class=\"field\"><label class=\"field-label\" for=\"dpa-i-headroom\">Growth headroom %</label><input type=\"number\" id=\"dpa-i-headroom\" min=\"0\" max=\"200\" value=\"10\"></div>\n      </div>\n\n      <p class=\"sub-head\">Server sizing workload</p>\n      <div class=\"field\">\n        <label class=\"field-label\">VMware registered in DPA?</label>\n        <p class=\"field-hint\">Registering VMware raises DPA server CPU &amp; RAM needs by ~50%.</p>\n        <div class=\"seg\" id=\"dpa-seg-vmware\"><button data-v=\"no\" class=\"active\">No</button><button data-v=\"yes\">Yes</button></div>\n      </div>\n      <div class=\"field\">\n        <label class=\"field-label\" for=\"dpa-i-centralusers\">DPA Central concurrent users</label>\n        <p class=\"field-hint\">Only relevant with multiple DPA servers. DPA Central links servers into one view; co-locate it on a monitoring DPA server.</p>\n        <input type=\"number\" id=\"dpa-i-centralusers\" min=\"0\" value=\"0\">\n      </div>\n    </div>\n\n    <!-- OUTPUTS -->\n    <div>\n      <div class=\"result-hero\">\n        <div class=\"out-label\">Total DPA licenses required\n          <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">Monitored instances + planned additions, then + growth headroom %. One license per monitored database instance.</span></span>\n        </div>\n        <div class=\"metric\" id=\"dpa-o-total\">\u2014</div>\n        <span class=\"badge\">Per monitored DB instance \u00b7 confirm in CPQ</span>\n      </div>\n      <div class=\"grid-out\">\n        <div class=\"out-card\">\n          <div class=\"out-label\">DBSH licenses\n            <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">Database Self-Hosted \u2014 any edition of any supported database type; VM metrics included.</span></span>\n          </div>\n          <div class=\"out-value\" id=\"dpa-o-dbsh\">\u2014</div>\n          <div class=\"note\" id=\"dpa-o-dbsh-note\"></div>\n        </div>\n        <div class=\"out-card\">\n          <div class=\"out-label\">DBSHDS licenses\n            <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">Database Self-Hosted DBaaS \u2014 supported DBaaS targets such as Azure SQL Database.</span></span>\n          </div>\n          <div class=\"out-value\" id=\"dpa-o-dbshds\">\u2014</div>\n          <div class=\"note\" id=\"dpa-o-dbshds-note\"></div>\n        </div>\n        <div class=\"out-card\">\n          <div class=\"out-label\">DPA servers required\n            <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">One DPA server monitors up to 250 instances. Beyond that, add servers and link them with DPA Central.</span></span>\n          </div>\n          <div class=\"out-value\" id=\"dpa-o-servers\">\u2014</div>\n          <div class=\"note\" id=\"dpa-o-servers-note\"></div>\n        </div>\n        <div class=\"out-card\">\n          <div class=\"out-label\">Deployment bracket\n            <span class=\"info\" tabindex=\"0\"><span class=\"ico\">i</span><span class=\"tip\">System-requirements bracket per DPA server: 1\u201320, 21\u201350, 51\u2013100 or 101\u2013250 monitored instances.</span></span>\n          </div>\n          <div class=\"out-value\" id=\"dpa-o-bracket\">\u2014</div>\n          <div class=\"note\" id=\"dpa-o-bracket-note\"></div>\n        </div>\n      </div>\n      <div id=\"dpa-o-flags\"></div>\n      <p class=\"sub-head contact-head\">Contact us</p>\n      <div class=\"contact-strip\">\n        <div class=\"contact-card\">\n          <span class=\"c-role\">Product Manager</span>\n          <span class=\"c-name\">Vera Pratiwi</span>\n          <a href=\"mailto:Vera.Pratiwi@westcon.com\">Vera.Pratiwi@westcon.com</a>\n        </div>\n        <div class=\"contact-card\">\n          <span class=\"c-role\">Sales Engineer</span>\n          <span class=\"c-name\">Teguh P. Mulyo</span>\n          <a href=\"mailto:teguh.mulyo@westcon.com\">teguh.mulyo@westcon.com</a>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- LICENSE SUMMARY -->\n  <div class=\"block\">\n    <p class=\"section-tag\">Licensing</p>\n    <h2>License summary</h2>\n    <p class=\"note\">Licensable quantities for the current scope. Confirm all quantities in CPQ.</p>\n    <table>\n      <thead><tr><th>License</th><th>Unit of measure</th><th>Quantity</th></tr></thead>\n      <tbody id=\"dpa-lic-body\"></tbody>\n    </table>\n  </div>\n\n  <!-- HARDWARE -->\n  <div class=\"block\">\n    <p class=\"section-tag\">Hardware sizing</p>\n    <h2>DPA server &amp; repository \u2014 Minimum vs Recommended</h2>\n    <p class=\"note\" id=\"dpa-hw-summary\"></p>\n    <div class=\"hw-grid\">\n      <div class=\"hw-card\">\n        <h3>1 \u00b7 Minimum hardware</h3>\n        <p class=\"cap\" id=\"dpa-hw-min-cap\"></p>\n        <table><thead><tr><th>Component</th><th>Qty</th><th>CPU</th><th>RAM</th><th>Storage</th></tr></thead><tbody id=\"dpa-hw-min\"></tbody></table>\n      </div>\n      <div class=\"hw-card\">\n        <h3>2 \u00b7 Recommended hardware</h3>\n        <p class=\"cap\" id=\"dpa-hw-rec-cap\"></p>\n        <table><thead><tr><th>Component</th><th>Qty</th><th>CPU</th><th>RAM</th><th>Storage</th></tr></thead><tbody id=\"dpa-hw-rec\"></tbody></table>\n      </div>\n    </div>\n    <p class=\"note\" style=\"margin-top:14px\">Repository RAM is shown as the database cache dedicated to DPA. Repository runs on SQL Server (Std/Ent), MySQL, Oracle or Azure SQL Database (Std tier+); Azure SQL Managed Instance is not supported as repository. Installing DPA on the repository server means meeting both spec sets combined.</p>\n  </div>\n\n  <!-- LICENSE TYPE REFERENCE -->\n  <div class=\"block\">\n    <p class=\"section-tag\">Reference</p>\n    <h2>License types</h2>\n    <table>\n      <thead><tr><th>License</th><th>Status</th><th>Coverage</th></tr></thead>\n      <tbody>\n        <tr><td>DBSH \u2014 Database Self-Hosted</td><td>Current subscription</td><td>Any edition of any supported database type (SQL Server, Oracle EE/SE/XE, MySQL, MariaDB, PostgreSQL/EDB, Db2, SAP ASE, SAP HANA, incl. RDS/Aurora/Cloud SQL/Azure equivalents). VM metrics included \u2014 no VM Option needed.</td></tr>\n        <tr><td>DBSHDS \u2014 DBSH DBaaS</td><td>Current subscription</td><td>Supported DBaaS targets, such as Azure SQL Database.</td></tr>\n        <tr><td>Category 1 / Category 2</td><td>Legacy (\u2264 DPA 2024.3)</td><td>Edition-based: Cat 1 required for Oracle EE &amp; SAP ASE; Cat 2 covers Express/lower-tier editions and Azure SQL DB. No functional difference between categories.</td></tr>\n        <tr><td>Azure SQL Database</td><td>Legacy (\u2264 DPA 2024.3)</td><td>Azure SQL Database instances.</td></tr>\n        <tr><td>VM Option</td><td>Legacy (\u2264 DPA 2024.3)</td><td>Add-on to Cat 1/Cat 2 for VM &amp; host metrics (Virtualization view).</td></tr>\n      </tbody>\n    </table>\n    <p class=\"note\" style=\"margin-top:12px\">DBSH &amp; DBSHDS keys are shared with SQL Sentry \u2014 e.g. a 10-license key can cover 5 instances in each product. AWS Marketplace deployments are metered per instance per hour through Amazon instead of DPA licenses. Trial allows 14 days of unlicensed monitoring.</p>\n  </div>\n\n  <!-- SIZING REFERENCE -->\n  <div class=\"block\">\n    <p class=\"section-tag\">Reference</p>\n    <h2>DPA 2026.2 sizing brackets (per DPA server)</h2>\n    <table>\n      <thead><tr><th>Monitored instances</th><th>DPA server (CPU \u00b7 RAM \u00b7 Disk)</th><th>Repository DB (CPU \u00b7 cache \u00b7 Disk)</th></tr></thead>\n      <tbody>\n        <tr><td>1 \u2013 20</td><td>4 cores \u00b7 10 GB \u00b7 40 GB</td><td>6 cores \u00b7 8 GB \u00b7 240 GB</td></tr>\n        <tr><td>21 \u2013 50</td><td>6 cores \u00b7 16 GB \u00b7 55 GB</td><td>8 cores \u00b7 16 GB \u00b7 600 GB</td></tr>\n        <tr><td>51 \u2013 100</td><td>8 cores \u00b7 24 GB \u00b7 75 GB</td><td>12 cores \u00b7 32 GB \u00b7 1.2 TB</td></tr>\n        <tr><td>101 \u2013 250</td><td>12 cores \u00b7 40 GB \u00b7 150 GB</td><td>16 cores \u00b7 64 GB \u00b7 3 TB</td></tr>\n      </tbody>\n    </table>\n    <p class=\"note\" style=\"margin-top:12px\">Above 250 instances, deploy additional DPA servers linked by DPA Central (0\u201350 users: 4 cores \u00b7 4 GB \u00b7 20 GB; 51\u2013100 users: 6 cores \u00b7 6 GB \u00b7 20 GB, added to a monitoring server's spec). Registering VMware raises DPA server CPU &amp; RAM by ~50%.</p>\n  </div>\n\n  <!-- ASSUMPTIONS -->\n  <div class=\"block assump\">\n    <h2>How this is calculated</h2>\n    <ul>\n      <li>DPA licenses are counted <strong>per monitored database instance</strong> (self-managed and Azure Marketplace). AWS Marketplace deployments are metered per instance per hour through Amazon and need no DPA licenses; licenses and metering cannot mix on one server.</li>\n      <li><strong>DBSH</strong> covers any edition of any supported database type and includes VM metrics. <strong>DBSHDS</strong> covers DBaaS targets such as Azure SQL Database. Legacy Cat 1 / Cat 2 / Azure SQL DB / VM Option licenses apply to DPA 2024.3 and earlier only.</li>\n      <li>Licenses float \u2014 more instances can be registered than licensed, with licenses assigned on the allocation page. Unlicensed instances stop collecting new data but keep historical data viewable.</li>\n      <li><strong>Server count</strong> = total instances \u00f7 250 (rounded up); instances are split evenly across servers and each server is sized by its bracket (1\u201320 / 21\u201350 / 51\u2013100 / 101\u2013250) from the DPA 2026.2 system requirements. Recommended uses the next bracket up plus a dedicated repository server.</li>\n      <li>Multiple DPA servers are linked via <strong>DPA Central</strong>, co-located on a monitoring server (not a dedicated box), sized by concurrent users.</li>\n    </ul>\n    <details>\n      <summary>Sources</summary>\n      <ul style=\"margin-top:12px\">\n        <li><a href=\"https://documentation.solarwinds.com/en/success_center/dpa/content/dpa_licensing_model.htm\">DPA licensing model</a> \u2014 per-instance counting, DBSH/DBSHDS, legacy Cat 1/Cat 2, floating licenses, SQL Sentry shared keys, AWS metering.</li>\n        <li><a href=\"https://documentation.solarwinds.com/en/Success_Center/DPA/Content/Install-DPA-Requirements.htm\">DPA 2026.2 system requirements</a> \u2014 DPA server &amp; repository brackets, DPA Central recommendations, repository database support.</li>\n      </ul>\n    </details>\n  </div>\n\n  <p class=\"foot-note\">Indicative SE sizing estimate for SolarWinds DPA. License quantities, license types, and final hardware must be validated in CPQ and against the customer's live environment and current DPA system-requirements documentation before quoting.</p>\n</div>\n</section>\n\n<script>\n(function(){\nfunction $id(x){return document.getElementById('sw-'+x);}\n\nvar DEVICES_PER_COLLECTOR=7000, FLOWS_PER_COLLECTOR=40000;\nvar NC_MIN={c:'4',r:16,d:'40 GB + SQL Express'};\nvar NC_REC={c:'8',r:32,d:'40 GB + dedicated SQL'};\nvar FLOW_REC={c:'8',r:32,d:'non-Express SQL'};\nvar AGENT={c:'<1',r:'~0.2',d:'on-host'};\nvar K8S={c:'~1',r:'~2',d:'in-cluster pods'};\n\nfunction fmt(n){return Math.round(n).toLocaleString('en-US');}\nfunction fmt1(n){return (Math.round(n*10)/10).toLocaleString('en-US');}\nfunction val(id){var el=$id(id);return el?parseFloat(el.value)||0:0;}\nfunction row(name,qty,spec,note){if(qty<=0)return '';return '<tr><td>'+name+(note?' <span style=\"color:var(--artifact-text-secondary)\">'+note+'</span>':'')+'</td><td>'+qty+'</td><td>'+spec.c+'</td><td>'+spec.r+' GB</td><td>'+spec.d+'</td></tr>';}\nfunction empty(){return '<tr><td colspan=\"5\" style=\"color:var(--artifact-text-secondary)\">No collectors/agents required for the current scope</td></tr>';}\n\nfunction calc(){\n  var netdev=val('i-netdev'), aps=val('i-aps');\n  var hosts=val('i-hosts'), hv=val('i-hv'), vms=val('i-vms'), cloud=val('i-cloud'), cont=val('i-containers'), storage=val('i-storage');\n  var flows=val('i-flows');\n  var apm=val('i-apm'), db=val('i-db');\n\n  // --- Synthetic uptime: endpoints x locations x protocols (private probes add as locations) ---\n  var endpoints=val('i-endpoints'), protocols=val('i-protocols'), locations=val('i-locations');\n  var usePP=$id('i-usepp').checked;\n  $id('pp-wrap').style.display=usePP?'block':'none';\n  var pp=usePP?val('i-pp'):0;\n  var totalLoc=locations+pp;\n  var uptime=Math.round(endpoints*totalLoc*protocols);\n  var txn=val('i-txn'), rum=val('i-rum'), logs=val('i-logs');\n\n  // live preview of the uptime formula\n  var prev=fmt(endpoints)+' endpoints \u00d7 '+fmt(totalLoc)+' location'+(totalLoc===1?'':'s');\n  if(usePP&&pp>0) prev+=' ('+fmt(locations)+' public + '+fmt(pp)+' private probe'+(pp===1?'':'s')+')';\n  prev+=' \u00d7 '+fmt(protocols)+' protocol'+(protocols===1?'':'s')+' = <strong>'+fmt(uptime)+' uptime checks</strong>';\n  $id('uptime-preview').innerHTML=prev;\n\n  var netRaw=netdev + aps/10;\n  var netQty=Math.ceil(netRaw);\n  var infraRaw=hosts + hv + vms/3 + cloud/3 + cont/10 + storage;\n  var infraQty=Math.ceil(infraRaw);\n  var synBundles=(uptime+txn)>0?Math.ceil((uptime + 5*txn)/10):0;\n  var rumBundles=rum>0?Math.ceil(rum/100000):0;\n\n  // Hero: primary Network + Infrastructure entitlements\n  $id('o-total').innerHTML=fmt(netQty+infraQty)+' <small>entitlements</small>';\n\n  $id('o-nico').innerHTML=fmt(netQty+infraQty)+' <small>entitlements</small>';\n  $id('o-nico-note').textContent=fmt(netQty)+' network \u00b7 '+fmt(infraQty)+' infrastructure';\n\n  $id('o-appdb').innerHTML=fmt(apm+db)+' <small>entities</small>';\n  $id('o-appdb-note').textContent=fmt(apm)+' APM services \u00b7 '+fmt(db)+' DB instances';\n\n  $id('o-dem').innerHTML=fmt(synBundles+rumBundles)+' <small>bundles</small>';\n  $id('o-dem-note').textContent=fmt(uptime)+' uptime + '+fmt(txn)+' txn ('+fmt(synBundles)+' bundle'+(synBundles===1?'':'s')+') \u00b7 '+fmt(rumBundles)+' RUM (100K)';\n\n  $id('o-logs').innerHTML=(logs>0?fmt1(logs):'0')+' <small>GB/day</small>';\n  $id('o-logs-note').textContent=logs>0?'Monthly log plan':'No log plan';\n\n  // License summary rows (quantity only)\n  var rows=[\n    ['Network Observability','Network entity (IP)',fmt1(netQty), netdev>0||aps>0],\n    ['Infrastructure Observability','Infrastructure host',fmt1(infraQty), (hosts+hv+vms+cloud+cont+storage)>0],\n    ['Application Observability (APM)','Application service',fmt1(apm), apm>0],\n    ['Database Observability','Database instance',fmt1(db), db>0],\n    ['Digital Experience \u2014 Synthetics','Bundle of 10 checks',fmt1(synBundles)+' <span style=\"color:var(--artifact-text-secondary)\">('+fmt(uptime)+' uptime + '+fmt(txn)+' txn)</span>', synBundles>0],\n    ['Digital Experience \u2014 RUM','100,000 pageviews/mo',fmt1(rumBundles), rumBundles>0],\n    ['Log Observability','GB / day ingest',fmt1(logs), logs>0]\n  ];\n  var html='';\n  rows.forEach(function(r){ if(r[3]){ html+='<tr><td>'+r[0]+'</td><td>'+r[1]+'</td><td>'+r[2]+'</td></tr>'; } });\n  if(!html) html='<tr><td colspan=\"3\" style=\"color:var(--artifact-text-secondary)\">Enter monitoring scope to build the estimate</td></tr>';\n  $id('lic-body').innerHTML=html;\n\n  // Collectors & agents\n  var collectors=netdev>0?Math.max(1,Math.ceil(netdev/DEVICES_PER_COLLECTOR)):0;\n  var flowColl=flows>0?Math.max(1,Math.ceil(flows/FLOWS_PER_COLLECTOR)):0;\n  var agents=hosts+db;\n  var k8s=cont>0?1:0;\n  var ppColl=usePP?pp:0;\n\n  $id('hw-summary').textContent='SaaS backend is fully hosted by SolarWinds. Customer-side footprint: '+collectors+' Network Collector'+(collectors===1?'':'s')+', '+agents+' agent'+(agents===1?'':'s')+(k8s?' + K8s collector':'')+(flowColl?' + '+flowColl+' flow collector'+(flowColl===1?'':'s'):'')+(ppColl?' + '+ppColl+' private probe'+(ppColl===1?'':'s'):'')+'.';\n\n  var mn='';\n  mn+=row('Network Collector',collectors,NC_MIN,'\u22647,000 devices each');\n  mn+=row('Observability Agent',agents,AGENT,'per host / DB \u00b7 OTLP 443');\n  mn+=row('SWO K8s Collector',k8s,K8S,'per cluster');\n  mn+=row('Private Synthetic Probe',ppColl,AGENT,'agent-based, in-network');\n  $id('hw-min').innerHTML=mn||empty();\n\n  var rc='';\n  rc+=row('Network Collector',collectors>0?collectors+1:0,NC_REC,'+1 standby (HA)');\n  if(flowColl>0) rc+=row('Dedicated Flow Collector',flowColl,FLOW_REC,'\u226440,000 flows/sec each');\n  rc+=row('Observability Agent',agents,AGENT,'per host / DB \u00b7 OTLP 443');\n  rc+=row('SWO K8s Collector',k8s,K8S,'per cluster');\n  rc+=row('Private Synthetic Probe',ppColl,AGENT,'agent-based, in-network');\n  $id('hw-rec').innerHTML=rc||empty();\n\n  $id('hw-note').innerHTML='Network Collector runs on Windows Server (min 4 cores / 16 GB, rec 8 cores / 32 GB, 40 GB + SQL). Each collector monitors up to 7,000 standard devices \u2014 deploy one per site or add collectors to scale. The Observability Agent is lightweight and runs on each monitored host/DB (no central server). APM libraries and RUM run in-app; synthetic uptime checks use SolarWinds public probe locations, with optional agent-based private probes for internal endpoints \u2014 each private probe counts as an additional test location.';\n\n  // Flags\n  var flags=[];\n  flags.push({t:'pos',m:'SaaS backend (storage, processing, web app) is hosted by SolarWinds \u2014 no servers, databases, or polling engines to size on-prem.'});\n  if(netdev>DEVICES_PER_COLLECTOR)flags.push({t:'warn',m:'More than 7,000 network devices \u2014 multiple Network Collectors required ('+collectors+' estimated). Deploy one per site where possible.'});\n  if(flows>0)flags.push({t:'warn',m:'Flow monitoring at scale \u2014 use a dedicated Network Collector with a non-Express SQL tier for flow data.'});\n  if(usePP&&pp>0)flags.push({t:'warn',m:pp+' private probe'+(pp===1?'':'s')+' added as location'+(pp===1?'':'s')+'. Private probes run as agents inside the customer network and are billed as uptime checks like any other location.'});\n  if(logs>0)flags.push({t:'warn',m:'Log ingestion is capped at ~200 GB/hour per organization regardless of plan; use exclusion filters for high-volume, low-value sources.'});\n  $id('o-flags').innerHTML=flags.map(function(f){return '<div class=\"flag '+f.t+'\">'+f.m+'</div>';}).join('');\n}\n\n['i-netdev','i-aps','i-hosts','i-hv','i-vms','i-cloud','i-containers','i-storage','i-flows','i-apm','i-db','i-endpoints','i-protocols','i-locations','i-pp','i-txn','i-rum','i-logs'].forEach(function(id){var el=$id(id);if(!el)return;el.addEventListener('input',calc);el.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();calc();}});});\n$id('i-usepp').addEventListener('change',calc);\ncalc();\n\n})();\n</script>\n<script>\n(function(){\nfunction $id(x){return document.getElementById('ea-'+x);}\n\nvar STANDARD_TIERS=[25,50,100,250,500,750,1000,1250,1500];\nvar ENTERPRISE_TIERS=[500,750,1000,1250,1500,1750,2000,2250,2500,3000,4000,5000,6000,7000,7500,8000,9000,10000,12500,15000,20000,25000,30000,35000,40000,45000,50000];\nvar PROTO_CAP={snmpv2:100000, snmpv3:72000, wmi:20000};\nvar PROTO_LABEL={snmpv2:'SNMPv2 (100k/poller)', snmpv3:'SNMPv3 (72k/poller)', wmi:'WMI/WinRM (20k/poller)'};\nvar SAM_PER_POLLER=40000, FPS_PER_POLLER=50000, AGENTS_PER_POLLER=1000, WMI_NODES_PER_POLLER=2000;\nvar state={tier:'advanced', edition:'auto', proto:'snmpv2'};\n\nvar MODULES=[\n ['Network performance monitoring (NPM)',1,1],\n ['Server & application management (SAM)',1,1],\n ['Log monitoring & analysis (LA)',1,1],\n ['IP address management (IPAM)',1,1],\n ['User & device tracking (UDT)',1,1],\n ['VoIP & network quality (VNQM)',1,1],\n ['Cloud monitoring',1,1],\n ['Additional web servers',1,1],\n ['ML anomaly-based alerting',0,1],\n ['Security vulnerability dashboard',0,1],\n ['Flow monitoring & analysis (NTA)',0,1],\n ['Network config management (NCM)',0,1],\n ['Virtualization management (VMAN)',0,1],\n ['Server config management (SCM)',0,1]\n];\n\n// SolarWinds Platform 2026.2 specs; poller bumped to 16 cores at large/xl to reach protocol caps\nvar SPECS={\n  small: {poller:{c:'4',r:16,d:'100 GB SSD'},  db:{c:'4',r:16,d:'100 GB SSD'},         web:{c:'4',r:16,d:'100 GB SSD'}},\n  medium:{poller:{c:'8',r:32,d:'100 GB SSD'},  db:{c:'8',r:32,d:'100 GB SSD'},         web:{c:'4',r:16,d:'100 GB SSD'}},\n  large: {poller:{c:'16',r:32,d:'100 GB SSD'}, db:{c:'8\u201316',r:'64\u2013128',d:'100\u2013400 GB SSD'}, web:{c:'10',r:32,d:'100 GB SSD'}},\n  xl:    {poller:{c:'16\u201324',r:64,d:'150 GB SSD'}, db:{c:'32',r:'256\u2013512',d:'2 TB SSD'},  web:{c:'10',r:32,d:'100 GB SSD'}}\n};\nvar ORDER=['small','medium','large','xl'];\nfunction nextTier(s){var i=ORDER.indexOf(s);return ORDER[Math.min(i+1,ORDER.length-1)];}\nfunction classify(el){if(el<=500)return 'small';if(el<=2000)return 'medium';if(el<=25000)return 'large';return 'xl';}\nvar LABEL={small:'Small',medium:'Medium',large:'Large',xl:'Extra Large'};\n\nfunction fmt(n){return Math.round(n).toLocaleString('en-US');}\nfunction val(id){return parseFloat($id(id).value)||0;}\nfunction bind(segId,key,attr){var seg=$id(segId);seg.querySelectorAll('button').forEach(function(b){b.addEventListener('click',function(){seg.querySelectorAll('button').forEach(function(x){x.classList.remove('active');});b.classList.add('active');state[key]=b.dataset[attr];calc();});});}\nfunction pickTier(cap,tiers){for(var i=0;i<tiers.length;i++){if(tiers[i]>=cap)return tiers[i];}return null;}\nfunction renderTierRow(elId,tiers,hit){$id(elId).innerHTML=tiers.map(function(t){return t===hit?'<strong style=\"color:var(--artifact-primary-brand)\">'+fmt(t)+'</strong>':fmt(t);}).join(' \u00b7 ');}\nfunction row(name,qty,spec,note){var id='hw-'+name.toLowerCase().replace(/[^a-z0-9]+/g,'-');if(qty<=0)return '';return '<tr data-glean-id=\"'+id+'\"><td>'+name+(note?' <span style=\"color:var(--artifact-text-secondary)\">'+note+'</span>':'')+'</td><td>'+qty+'</td><td>'+spec.c+'</td><td>'+spec.r+' GB</td><td>'+spec.d+'</td></tr>';}\n\nfunction renderModules(){\n  var essHit=state.tier==='essentials', advHit=state.tier==='advanced';\n  $id('th-ess').className=essHit?'hit':'';\n  $id('th-adv').className=advHit?'hit':'';\n  $id('module-body').innerHTML=MODULES.map(function(m){\n    var e=m[1]?'<span class=\"yes\">\u2713</span>':'<span class=\"no\">\u2014</span>';\n    var a=m[2]?'<span class=\"yes\">\u2713</span>':'<span class=\"no\">\u2014</span>';\n    return '<tr><td>'+m[0]+'</td><td class=\"'+(essHit?'hit':'')+'\">'+e+'</td><td class=\"'+(advHit?'hit':'')+'\">'+a+'</td></tr>';\n  }).join('');\n}\n\nfunction renderHardware(cap,pollers,apeCount,users,edition){\n  var epn=Math.max(1,val('i-epn'));\n  var elements=Math.round(cap*epn);\n  var size=classify(elements), recSize=nextTier(size);\n  var sMin=SPECS[size], sRec=SPECS[recSize];\n\n  $id('hw-summary').textContent='~'+fmt(elements)+' elements ('+fmt(cap)+' nodes \u00d7 '+epn+') via '+PROTO_LABEL[state.proto]+' \u2192 '+LABEL[size]+' deployment \u00b7 '+pollers+' polling engine'+(pollers>1?'s':'')+' (1 main + '+apeCount+' APE).';\n  $id('hw-min-cap').textContent=LABEL[size]+' tier \u00b7 documented minimum spec';\n  $id('hw-rec-cap').textContent=LABEL[recSize]+'-tier spec \u00b7 +HA & redundancy headroom';\n\n  var webMin=Math.max(0,Math.ceil(users/50)-1);\n  var webRec=Math.max(users>0?1:0,Math.ceil(users/25)-1,webMin);\n  var apeNote=edition==='Enterprise'?PROTO_LABEL[state.proto].split(' ')[0]+' capacity':'requires Enterprise license';\n\n  var mo='';\n  mo+=row('Main polling server',1,sMin.poller,'Web Console + main poller');\n  if(apeCount>0) mo+=row('Additional Polling Engine',apeCount,sMin.poller,apeNote);\n  mo+=row('Database server',1,sMin.db,'');\n  if(webMin>0) mo+=row('Additional Web Server',webMin,sMin.web,'25\u201350 users each');\n  $id('hw-min-osh').innerHTML=mo;\n\n  var apeRec=apeCount>0?apeCount+1:apeCount;\n  var ro='';\n  ro+=row('Main polling server',1,sRec.poller,'Web Console + main poller');\n  if(apeRec>0) ro+=row('Additional Polling Engine',apeRec,sRec.poller,'+1 redundancy');\n  ro+=row('Database server',2,sRec.db,'HA pair');\n  ro+=row('Additional Web Server',Math.max(webRec,1),sRec.web,'HA / ~25 users each');\n  $id('hw-rec-osh').innerHTML=ro;\n\n  return {webMin:webMin,webRec:webRec};\n}\n\nfunction calc(){\n  var nodes=val('i-nodes'), add=val('i-add'), headroom=val('i-headroom');\n  var cap=Math.ceil((nodes+add)*(1+headroom/100));\n\n  var epn=Math.max(1,val('i-epn'));\n  var elements=Math.round(cap*epn);\n  var components=val('i-components'), agents=val('i-agents'), users=val('i-webusers');\n  var fpsInput=val('i-fps');\n  var ntaActive=(state.tier==='advanced');\n  var fps=ntaActive?fpsInput:0;\n  var protoCap=PROTO_CAP[state.proto];\n  var totalNodes=nodes+add;\n\n  var dEl=Math.ceil(elements/protoCap);\n  var dSam=Math.ceil(components/SAM_PER_POLLER);\n  var dFps=Math.ceil(fps/FPS_PER_POLLER);\n  var dAg=Math.ceil(agents/AGENTS_PER_POLLER);\n  var dWmi=state.proto==='wmi'?Math.ceil(totalNodes/WMI_NODES_PER_POLLER):0;\n  var pollers=Math.max(1,dEl,dSam,dFps,dAg,dWmi);\n  var apeCount=Math.max(0,pollers-1);\n  var apeNeeded=apeCount>0;\n\n  var mustEnterprise=(cap>1500||apeNeeded);\n  var stdForced=(state.edition==='standard'&&mustEnterprise);\n  var edition;\n  if(state.edition==='enterprise')edition='Enterprise';\n  else if(state.edition==='standard')edition=mustEnterprise?'Enterprise':'Standard';\n  else edition=mustEnterprise?'Enterprise':'Standard';\n\n  var tiers=edition==='Enterprise'?ENTERPRISE_TIERS:STANDARD_TIERS;\n  var tier=pickTier(cap,tiers);\n  if(tier===null){edition='Enterprise';tiers=ENTERPRISE_TIERS;tier=pickTier(cap,tiers);}\n\n  var tierName=state.tier==='essentials'?'Essentials':'Advanced';\n\n  $id('o-tier').innerHTML=tier?fmt(tier)+' <small>nodes</small>':'Above listed tiers';\n  $id('o-tiername').textContent='OSH '+tierName+' \u00b7 '+edition;\n\n  $id('o-capacity').innerHTML=fmt(cap)+' <small>nodes</small>';\n  var bp=[fmt(nodes)+' licensed'];\n  if(add>0)bp.push(fmt(add)+' additions');\n  if(headroom>0)bp.push('+'+headroom+'% headroom');\n  $id('o-capacity-break').textContent=bp.join(' \u00b7 ');\n\n  $id('o-edition').textContent=edition;\n  $id('o-edition-note').textContent=edition==='Enterprise'?'Includes APEs, HA, EOC, lab licenses & Advanced Support':'Includes additional web servers; HA available as add-on';\n\n  $id('o-pollers').innerHTML=pollers+' <small>engine'+(pollers>1?'s':'')+'</small>';\n  $id('o-pollers-note').textContent='1 main + '+apeCount+' APE'+(apeCount===1?'':'s');\n\n  var hw=renderHardware(cap,pollers,apeCount,users,edition);\n  var totalWeb=1+hw.webMin;\n  $id('o-web').innerHTML=totalWeb+' <small>total</small>';\n  $id('o-web-note').textContent=hw.webMin>0?('main + '+hw.webMin+' additional web server'+(hw.webMin>1?'s':'')):'main server handles '+(users||0)+' users';\n\n  var flags=[];\n  if(stdForced)flags.push({t:'warn',m:'Standard edition is not possible '+(cap>1500?'above 1,500 nodes':'when APEs are required')+' \u2014 escalated to Enterprise.'});\n  else if(cap>1500)flags.push({t:'warn',m:'Above 1,500 nodes \u2014 Enterprise edition is mandatory.'});\n  if(apeNeeded&&edition==='Enterprise')flags.push({t:'warn',m:'Sizing requires '+apeCount+' Additional Polling Engine'+(apeCount>1?'s':'')+' \u2014 APEs are only available with an Enterprise license.'});\n  if(state.tier==='essentials'&&fpsInput>0)flags.push({t:'warn',m:'Flow monitoring (NTA) requires the Advanced tier \u2014 flows were not counted for Essentials sizing.'});\n  if(state.proto==='wmi'&&totalNodes>2000)flags.push({t:'warn',m:'WMI/WinRM caps at 2,000 nodes per poller \u2014 multiple pollers required.'});\n  if(tier&&(tier-cap)>tier*0.2)flags.push({t:'pos',m:'Comfortable buffer: tier ('+fmt(tier)+') sits well above required capacity ('+fmt(cap)+').'});\n  $id('o-flags').innerHTML=flags.map(function(f){return '<div class=\"flag '+f.t+'\">'+f.m+'</div>';}).join('');\n\n  renderTierRow('tiers-standard',STANDARD_TIERS,edition==='Standard'?tier:null);\n  renderTierRow('tiers-enterprise',ENTERPRISE_TIERS.slice(0,12),edition==='Enterprise'?tier:null);\n  $id('tr-standard').classList.toggle('hit',edition==='Standard');\n  $id('tr-enterprise').classList.toggle('hit',edition==='Enterprise');\n\n  $id('hw-poller-note').innerHTML='Poller count is the maximum across workload dimensions. CPU = cores \u00b7 RAM in GB. Element-heavy pollers need 16 cores to reach the protocol cap; adding cores raises it (SNMPv2 \u2192150k, SNMPv3 \u2192100k). Additional Polling Engines require an Enterprise license.';\n\n  renderModules();\n}\n\n['i-nodes','i-add','i-headroom','i-epn','i-components','i-agents','i-fps','i-webusers'].forEach(function(id){var el=$id(id);el.addEventListener('input',calc);el.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();calc();}});});\nbind('seg-tier','tier','t');bind('seg-edition','edition','ed');bind('seg-proto','proto','p');\ncalc();\n\n})();\n</script>\n<script>\n(function(){\nfunction $id(x){return document.getElementById('pr-'+x);}\n\nvar STANDARD_TIERS=[25,50,100,250,500,750,1000,1250,1500];\nvar ENTERPRISE_TIERS=[500,750,1000,1250,1500,1750,2000,2250,2500,3000,4000,5000,6000,7000,7500,8000,9000,10000,12500,15000,20000,25000,30000,35000,40000,45000,50000];\nvar PRICE=17.50, CLOUD_SHARE=3, CONTAINER_SHARE=10, THINAP_SHARE=10, SRM_NODES_PER_ARRAY=5;\nvar PROTO_CAP={snmpv2:100000, snmpv3:72000, wmi:20000};\nvar PROTO_LABEL={snmpv2:'SNMPv2 (100k/poller)', snmpv3:'SNMPv3 (72k/poller)', wmi:'WMI/WinRM (20k/poller)'};\nvar SAM_PER_POLLER=40000, FPS_PER_POLLER=50000, AGENTS_PER_POLLER=1000, WMI_NODES_PER_POLLER=2000;\nvar DEVICES_PER_COLLECTOR=7000, DEVICES_PER_COLLECTOR_SMALL=5000, FLOWS_PER_COLLECTOR=40000;\nvar state={edition:'auto', overage:'no', proto:'snmpv2'};\n\n// SolarWinds Platform 2026.2 specs; poller bumped to 16 cores at large/xl to reach protocol caps\nvar SPECS={\n  small: {poller:{c:'4',r:16,d:'100 GB SSD'},  db:{c:'4',r:16,d:'100 GB SSD'},         web:{c:'4',r:16,d:'100 GB SSD'}},\n  medium:{poller:{c:'8',r:32,d:'100 GB SSD'},  db:{c:'8',r:32,d:'100 GB SSD'},         web:{c:'4',r:16,d:'100 GB SSD'}},\n  large: {poller:{c:'16',r:32,d:'100 GB SSD'}, db:{c:'8\u201316',r:'64\u2013128',d:'100\u2013400 GB SSD'}, web:{c:'10',r:32,d:'100 GB SSD'}},\n  xl:    {poller:{c:'16\u201324',r:64,d:'150 GB SSD'}, db:{c:'32',r:'256\u2013512',d:'2 TB SSD'},  web:{c:'10',r:32,d:'100 GB SSD'}}\n};\nvar COLLECTOR_SMALL={c:'8',r:32,d:'SQL / flow-dependent'};\nvar COLLECTOR_LARGE={c:'16',r:32,d:'SQL / flow-dependent'};\nvar AGENT_SPEC={c:'<1',r:'~0.2',d:'on-host'};\nvar ORDER=['small','medium','large','xl'];\nfunction nextTier(s){var i=ORDER.indexOf(s);return ORDER[Math.min(i+1,ORDER.length-1)];}\nfunction classify(el){if(el<=500)return 'small';if(el<=2000)return 'medium';if(el<=25000)return 'large';return 'xl';}\nvar LABEL={small:'Small',medium:'Medium',large:'Large',xl:'Extra Large'};\n\nfunction fmt(n){return Math.round(n).toLocaleString('en-US');}\nfunction money(n){return '$'+Math.round(n).toLocaleString('en-US');}\nfunction val(id){return parseFloat($id(id).value)||0;}\nfunction bind(segId,key,attr){var seg=$id(segId);seg.querySelectorAll('button').forEach(function(b){b.addEventListener('click',function(){seg.querySelectorAll('button').forEach(function(x){x.classList.remove('active');});b.classList.add('active');state[key]=b.dataset[attr];calc();});});}\nfunction pickTier(cap,tiers){for(var i=0;i<tiers.length;i++){if(tiers[i]>=cap)return tiers[i];}return null;}\nfunction renderTierRow(elId,tiers,hit){$id(elId).innerHTML=tiers.map(function(t){return t===hit?'<strong style=\"color:var(--artifact-primary-brand)\">'+fmt(t)+'</strong>':fmt(t);}).join(' \u00b7 ');}\nfunction row(name,qty,spec,note){var id='hw-'+name.toLowerCase().replace(/[^a-z0-9]+/g,'-');if(qty<=0)return '';return '<tr data-glean-id=\"'+id+'\"><td>'+name+(note?' <span style=\"color:var(--artifact-text-secondary)\">'+note+'</span>':'')+'</td><td>'+qty+'</td><td>'+spec.c+'</td><td>'+spec.r+' GB</td><td>'+spec.d+'</td></tr>';}\nfunction empty(){return '<tr><td colspan=\"5\" style=\"color:var(--artifact-text-secondary)\">Not in scope</td></tr>';}\n\nfunction renderHardware(cap){\n  var epn=Math.max(1,val('i-epn'));\n  var nodes=val('i-nodes')+val('i-add');\n  var elements=Math.round(cap*epn);\n  var components=val('i-components'), fps=val('i-fps'), agents=val('i-agents'), users=val('i-webusers');\n  var protoCap=PROTO_CAP[state.proto];\n\n  // Poller demand across dimensions\n  var dEl=Math.ceil(elements/protoCap);\n  var dSam=Math.ceil(components/SAM_PER_POLLER);\n  var dFps=Math.ceil(fps/FPS_PER_POLLER);\n  var dAg=Math.ceil(agents/AGENTS_PER_POLLER);\n  var dWmi=state.proto==='wmi'?Math.ceil(nodes/WMI_NODES_PER_POLLER):0;\n  var pollers=Math.max(1,dEl,dSam,dFps,dAg,dWmi);\n  var apeMin=Math.max(0,pollers-1);\n\n  var size=classify(elements), recSize=nextTier(size);\n  var sMin=SPECS[size], sRec=SPECS[recSize];\n\n  $id('hw-summary').textContent='~'+fmt(elements)+' elements ('+fmt(cap)+' nodes \u00d7 '+epn+') via '+PROTO_LABEL[state.proto]+' \u2192 '+LABEL[size]+' deployment \u00b7 '+pollers+' polling engine'+(pollers>1?'s':'')+' (1 main + '+apeMin+' APE).';\n  $id('hw-min-cap').textContent=LABEL[size]+' tier \u00b7 documented minimum spec';\n  $id('hw-rec-cap').textContent=LABEL[recSize]+'-tier spec \u00b7 +HA & redundancy headroom';\n\n  // Web servers\n  var webMin=Math.max(0,Math.ceil(users/50)-1);\n  var webRec=Math.max(users>0?1:0,Math.ceil(users/25)-1,webMin);\n\n  // MIN OSH\n  var mo='';\n  mo+=row('Main polling server',1,sMin.poller,'Web Console + main poller');\n  if(apeMin>0) mo+=row('Additional Polling Engine',apeMin,sMin.poller,PROTO_LABEL[state.proto].split(' ')[0]+' capacity');\n  mo+=row('Database server',1,sMin.db,'');\n  if(webMin>0) mo+=row('Additional Web Server',webMin,sMin.web,'25\u201350 users each');\n  $id('hw-min-osh').innerHTML=mo;\n\n  // REC OSH\n  var apeRec=apeMin>0?apeMin+1:apeMin;\n  var ro='';\n  ro+=row('Main polling server',1,sRec.poller,'Web Console + main poller');\n  if(apeRec>0) ro+=row('Additional Polling Engine',apeRec,sRec.poller,'+1 redundancy');\n  ro+=row('Database server',2,sRec.db,'HA pair');\n  ro+=row('Additional Web Server',Math.max(webRec,1),sRec.web,'HA / ~25 users each');\n  $id('hw-rec-osh').innerHTML=ro;\n\n  // SaaS side\n  var saasDev=val('i-saasdev'), saasAgent=val('i-saasagent'), saasAgentless=val('i-saasagentless'), flows=val('i-flows');\n  var collDevices=saasDev+saasAgentless;\n  var collMin=collDevices>0?Math.max(1,Math.ceil(collDevices/DEVICES_PER_COLLECTOR)):0;\n  var perColl=collMin>0?Math.ceil(collDevices/collMin):0;\n  var collSpecMin=perColl<=DEVICES_PER_COLLECTOR_SMALL?COLLECTOR_SMALL:COLLECTOR_LARGE;\n\n  // MIN SaaS\n  var ms='';\n  if(collMin>0) ms+=row('Network Collector',collMin,collSpecMin,'~'+fmt(perColl)+' devices each (\u22647,000)');\n  if(saasAgent>0) ms+=row('Observability Agent',saasAgent,AGENT_SPEC,'per host \u00b7 OTLP 443, no central server');\n  $id('hw-min-saas').innerHTML=ms||empty();\n\n  // REC SaaS\n  var collRec=collDevices>0?collMin+1:0;\n  var rs='';\n  if(collRec>0) rs+=row('Network Collector',collRec,COLLECTOR_LARGE,'\u22647,000 devices each \u00b7 +1 standby (HA)');\n  if(flows>0) rs+=row('Dedicated Flow Collector',Math.max(1,Math.ceil(flows/FLOWS_PER_COLLECTOR)),COLLECTOR_LARGE,'\u226440,000 flows/sec \u00b7 non-Express SQL');\n  if(saasAgent>0) rs+=row('Observability Agent',saasAgent,AGENT_SPEC,'per host \u00b7 OTLP 443, no central server');\n  $id('hw-rec-saas').innerHTML=rs||empty();\n\n  // Poller note\n  var drivers=[];\n  if(dEl===pollers)drivers.push('element polling');\n  if(dSam===pollers&&components>0)drivers.push('SAM components');\n  if(dFps===pollers&&fps>0)drivers.push('flows');\n  if(dAg===pollers&&agents>0)drivers.push('agents');\n  if(dWmi===pollers&&dWmi>0)drivers.push('WMI node cap');\n  $id('hw-poller-note').innerHTML='Poller count is driven by: <strong>'+(drivers.join(', ')||'element polling')+'</strong>. CPU = cores \u00b7 RAM in GB. Element-heavy pollers need 16 cores to reach the protocol cap; adding cores raises it (SNMPv2 \u2192150k, SNMPv3 \u2192100k). SaaS agents run on each monitored host and need no dedicated server.';\n}\n\nfunction calc(){\n  var nodes=val('i-nodes'), cloud=val('i-cloud'), containers=val('i-containers'), thinap=val('i-thinap');\n  var add=val('i-add'), headroom=val('i-headroom');\n  var cloudF=cloud/CLOUD_SHARE, contF=containers/CONTAINER_SHARE, thinF=thinap/THINAP_SHARE;\n  var cap=Math.ceil((nodes+add+cloudF+contF+thinF)*(1+headroom/100));\n\n  var edition;\n  if(state.edition==='standard')edition='Standard';else if(state.edition==='enterprise')edition='Enterprise';\n  else edition=(cap>1500)?'Enterprise':'Standard';\n  var forced=(cap>1500); if(forced)edition='Enterprise';\n  var tiers=edition==='Enterprise'?ENTERPRISE_TIERS:STANDARD_TIERS;\n  var tier=pickTier(cap,tiers);\n  if(tier===null){edition='Enterprise';tiers=ENTERPRISE_TIERS;tier=pickTier(cap,tiers);}\n\n  $id('o-tier').innerHTML=tier?fmt(tier)+' <small>nodes</small>':'Above listed tiers';\n  $id('o-edition').textContent='Premier '+edition;\n  $id('o-capacity').innerHTML=fmt(cap)+' <small>nodes</small>';\n  var bp=[fmt(nodes)+' full'];\n  if(add>0)bp.push(fmt(add)+' additions');\n  if(cloud>0)bp.push(fmt(cloudF)+' cloud (\u00f73)');\n  if(containers>0)bp.push(fmt(contF)+' containers (\u00f710)');\n  if(thinap>0)bp.push(fmt(thinF)+' thin-AP (\u00f710)');\n  if(headroom>0)bp.push('+'+headroom+'% headroom');\n  $id('o-capacity-break').textContent=bp.join(' \u00b7 ');\n  $id('o-saas').innerHTML=tier?fmt(tier)+' <small>nodes</small>':'\u2014';\n\n  if(state.overage==='yes'&&tier){var burst=Math.min(Math.round(tier*0.25),500);$id('o-overage').innerHTML='+'+fmt(burst)+' <small>nodes</small>';$id('o-overage-note').textContent='Effective ceiling \u2248 '+fmt(tier+burst)+' nodes';}\n  else{$id('o-overage').textContent='\u2014';$id('o-overage-note').textContent='Enable overage to calculate burst';}\n\n  var arrays=val('i-arrays'), wpm=val('i-wpm');\n  var sp=[]; if(arrays>0)sp.push(fmt(arrays)+' arrays (~'+fmt(arrays*SRM_NODES_PER_ARRAY)+' nodes from Tungsten)'); if(wpm>0)sp.push(fmt(wpm)+' WPM txns');\n  $id('o-srm-note').textContent=sp.length?sp.join(' \u00b7 ')+' \u00b7 unlimited today':'Unlimited today; no node impact in 2026.2';\n\n  var ir=val('i-ir');\n  $id('o-ir').textContent=ir>0?fmt(ir)+' users':'Bundled';\n  $id('o-ir-note').textContent=ir>0?'IR Pro included by tier; size extra users separately':'Included by Premier tier (Pro)';\n\n  var flags=[];\n  if(forced&&state.edition==='standard')flags.push({t:'warn',m:'Standard not possible above 1,500 nodes. Escalated to Enterprise.'});\n  if(cap>1500)flags.push({t:'warn',m:'Above 1,500 nodes \u2014 Enterprise edition is mandatory.'});\n  if(state.overage==='yes')flags.push({t:'warn',m:'Overage requires SWIP + outbound connectivity \u2014 not available for air-gapped sites.'});\n  if(state.proto==='wmi'&&(val('i-nodes')+val('i-add'))>2000)flags.push({t:'warn',m:'WMI/WinRM caps at 2,000 nodes per poller \u2014 multiple pollers required.'});\n  if(tier&&(tier-cap)>tier*0.2)flags.push({t:'pos',m:'Comfortable buffer: tier ('+fmt(tier)+') sits well above required capacity ('+fmt(cap)+').'});\n  $id('o-flags').innerHTML=flags.map(function(f){return '<div class=\"flag '+f.t+'\">'+f.m+'</div>';}).join('');\n\n  renderTierRow('tiers-standard',STANDARD_TIERS,edition==='Standard'?tier:null);\n  renderTierRow('tiers-enterprise',ENTERPRISE_TIERS.slice(0,12),edition==='Enterprise'?tier:null);\n  $id('tr-standard').classList.toggle('hit',edition==='Standard');\n  $id('tr-enterprise').classList.toggle('hit',edition==='Enterprise');\n\n  renderHardware(cap);\n}\n\n['i-nodes','i-cloud','i-containers','i-thinap','i-add','i-headroom','i-arrays','i-wpm','i-ir','i-epn','i-components','i-agents','i-fps','i-webusers','i-saasdev','i-saasagent','i-saasagentless','i-flows'].forEach(function(id){var el=$id(id);el.addEventListener('input',calc);el.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();calc();}});});\nbind('seg-edition','edition','ed');bind('seg-overage','overage','ov');bind('seg-proto','proto','p');\ncalc();\n\n})();\n</script>\n\n<script>\n(function(){\nfunction $id(x){return document.getElementById('dpa-'+x);}\n\nvar MAX_PER_SERVER=250;\nvar BRACKETS=[\n  {max:20, label:'1\\u201320', app:{c:'4',r:'10',d:'40 GB'},  repo:{c:'6',r:'8',d:'240 GB'}},\n  {max:50, label:'21\\u201350', app:{c:'6',r:'16',d:'55 GB'},  repo:{c:'8',r:'16',d:'600 GB'}},\n  {max:100,label:'51\\u2013100',app:{c:'8',r:'24',d:'75 GB'},  repo:{c:'12',r:'32',d:'1.2 TB'}},\n  {max:250,label:'101\\u2013250',app:{c:'12',r:'40',d:'150 GB'},repo:{c:'16',r:'64',d:'3 TB'}}\n];\nvar CENTRAL_SMALL={c:'+4',r:'+4',d:'+20 GB'};\nvar CENTRAL_LARGE={c:'+6',r:'+6',d:'+20 GB'};\nvar state={vmware:'no'};\n\nfunction fmt(n){return Math.round(n).toLocaleString('en-US');}\nfunction val(id){var el=$id(id);return el?parseFloat(el.value)||0:0;}\nfunction bracketIdx(n){for(var i=0;i<BRACKETS.length;i++){if(n<=BRACKETS[i].max)return i;}return BRACKETS.length-1;}\nfunction row(name,qty,spec,note){if(qty<=0)return '';return '<tr><td>'+name+(note?' <span style=\"color:var(--artifact-text-secondary)\">'+note+'</span>':'')+'</td><td>'+qty+'</td><td>'+spec.c+'</td><td>'+spec.r+' GB</td><td>'+spec.d+'</td></tr>';}\nfunction empty(){return '<tr><td colspan=\"5\" style=\"color:var(--artifact-text-secondary)\">Enter monitored instances to size the deployment</td></tr>';}\n\nfunction calc(){\n  var dbsh=val('i-dbsh'), dbshds=val('i-dbshds'), add=val('i-add'), headroom=val('i-headroom');\n  var centralUsers=val('i-centralusers');\n  var total=Math.ceil((dbsh+dbshds+add)*(1+headroom/100));\n  var dbshLic=Math.ceil((dbsh+add)*(1+headroom/100));\n  var dbshdsLic=Math.ceil(dbshds*(1+headroom/100));\n\n  $id('o-total').innerHTML=fmt(total)+' <small>licenses</small>';\n\n  $id('o-dbsh').innerHTML=fmt(dbshLic)+' <small>instances</small>';\n  $id('o-dbsh-note').textContent=dbsh>0||add>0?fmt(dbsh)+' current'+(add>0?' + '+fmt(add)+' additions':'')+(headroom>0?' + '+headroom+'% headroom':''):'No self-hosted instances';\n\n  $id('o-dbshds').innerHTML=fmt(dbshdsLic)+' <small>instances</small>';\n  $id('o-dbshds-note').textContent=dbshds>0?fmt(dbshds)+' DBaaS'+(headroom>0?' + '+headroom+'% headroom':''):'No DBaaS instances';\n\n  var servers=total>0?Math.ceil(total/MAX_PER_SERVER):0;\n  var perServer=servers>0?Math.ceil(total/servers):0;\n  var bi=perServer>0?bracketIdx(perServer):0;\n  var bRec=Math.min(bi+1,BRACKETS.length-1);\n\n  $id('o-servers').innerHTML=servers>0?servers+' <small>server'+(servers>1?'s':'')+'</small>':'\\u2014';\n  $id('o-servers-note').textContent=servers>1?('~'+fmt(perServer)+' instances each \\u00b7 linked via DPA Central'):(servers===1?'Single server, \\u2264250 instances':'');\n\n  $id('o-bracket').textContent=perServer>0?BRACKETS[bi].label+' instances':'\\u2014';\n  $id('o-bracket-note').textContent=perServer>0?'Per DPA server ('+fmt(perServer)+' instances)':'';\n\n  var rows=[];\n  if(dbshLic>0)rows.push(['DBSH \\u2014 Database Self-Hosted','Monitored DB instance',fmt(dbshLic)]);\n  if(dbshdsLic>0)rows.push(['DBSHDS \\u2014 DBSH DBaaS','Monitored DBaaS instance',fmt(dbshdsLic)]);\n  var html=rows.map(function(r){return '<tr><td>'+r[0]+'</td><td>'+r[1]+'</td><td>'+r[2]+'</td></tr>';}).join('');\n  if(rows.length>1)html+='<tr class=\"total\"><td>Total</td><td>Monitored instances</td><td>'+fmt(total)+'</td></tr>';\n  $id('lic-body').innerHTML=html||'<tr><td colspan=\"3\" style=\"color:var(--artifact-text-secondary)\">Enter monitored instances to build the estimate</td></tr>';\n\n  var vm=state.vmware==='yes';\n  if(perServer>0){\n    var sMin=BRACKETS[bi], sRec=BRACKETS[bRec];\n    $id('hw-summary').textContent=fmt(total)+' monitored instances \\u2192 '+servers+' DPA server'+(servers>1?'s':'')+' ('+sMin.label+' bracket each)'+(vm?' \\u00b7 VMware registered: +50% CPU/RAM on DPA servers':'')+'.';\n    $id('hw-min-cap').textContent=sMin.label+'-instance bracket \\u00b7 documented minimum spec';\n    $id('hw-rec-cap').textContent=sRec.label+'-instance bracket spec \\u00b7 headroom + dedicated repository';\n\n    var centralSpec=centralUsers>50?CENTRAL_LARGE:CENTRAL_SMALL;\n    var mn='';\n    mn+=row('DPA Server',servers,sMin.app,'\\u2264250 instances each'+(vm?' \\u00b7 +50% for VMware':''));\n    mn+=row('Repository DB server',servers,sMin.repo,'cache GB \\u00b7 SQL Server / MySQL / Oracle');\n    if(servers>1)mn+=row('DPA Central',1,centralSpec,'co-located on a DPA server \\u00b7 '+(centralUsers>50?'51\\u2013100':'0\\u201350')+' users');\n    $id('hw-min').innerHTML=mn||empty();\n\n    var rc='';\n    rc+=row('DPA Server',servers,sRec.app,'next-bracket headroom'+(vm?' \\u00b7 +50% for VMware':''));\n    rc+=row('Repository DB server',servers,sRec.repo,'dedicated \\u00b7 cache GB');\n    if(servers>1)rc+=row('DPA Central',1,centralSpec,'co-located \\u00b7 '+(centralUsers>50?'51\\u2013100':'0\\u201350')+' users');\n    $id('hw-rec').innerHTML=rc||empty();\n  }else{\n    $id('hw-summary').textContent='';\n    $id('hw-min-cap').textContent='';$id('hw-rec-cap').textContent='';\n    $id('hw-min').innerHTML=empty();$id('hw-rec').innerHTML=empty();\n  }\n\n  var flags=[];\n  if(total>MAX_PER_SERVER)flags.push({t:'warn',m:'More than 250 monitored instances \\u2014 '+servers+' DPA servers required, linked through DPA Central for a single view.'});\n  if(vm)flags.push({t:'warn',m:'VMware registered in DPA \\u2014 increase DPA server CPU and RAM requirements by ~50%.'});\n  if(centralUsers>100)flags.push({t:'warn',m:'DPA Central is sized up to 100 concurrent users \\u2014 validate larger user counts with SolarWinds.'});\n  if(total>0)flags.push({t:'pos',m:'DBSH/DBSHDS keys are shared with SQL Sentry \\u2014 one key can cover instances in either product.'});\n  $id('o-flags').innerHTML=flags.map(function(f){return '<div class=\"flag '+f.t+'\">'+f.m+'</div>';}).join('');\n}\n\n['i-dbsh','i-dbshds','i-add','i-headroom','i-centralusers'].forEach(function(id){var el=$id(id);el.addEventListener('input',calc);el.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();calc();}});});\n(function(){var seg=$id('seg-vmware');seg.querySelectorAll('button').forEach(function(b){b.addEventListener('click',function(){seg.querySelectorAll('button').forEach(function(x){x.classList.remove('active');});b.classList.add('active');state.vmware=b.dataset.v;calc();});});})();\ncalc();\n\n})();\n</script>\n\\n<script>\n(function(){\n  var btns=document.querySelectorAll('.tab-btn'),panels=document.querySelectorAll('.tab-panel');\n  btns.forEach(function(b){b.addEventListener('click',function(){\n    btns.forEach(function(x){x.classList.remove('active');});\n    panels.forEach(function(x){x.classList.remove('active');});\n    b.classList.add('active');\n    document.getElementById('panel-'+b.dataset.tab).classList.add('active');\n    window.scrollTo(0,0);\n  });});\n})();\n</script>\n\n<script>\n(function(){\nvar DICT={\"Contact us\":\"Hubungi kami\",\"Licensing inputs\": \"Input lisensi\", \"Monitoring scope (entities)\": \"Cakupan monitoring (entitas)\", \"Reference\": \"Referensi\", \"Licensing\": \"Lisensi\", \"Hardware sizing\": \"Sizing hardware\", \"Customer-side sizing\": \"Sizing sisi pelanggan\", \"How this is calculated\": \"Cara perhitungan\", \"Sources\": \"Sumber\", \"Contact\": \"Kontak\", \"1 \u00b7 Minimum hardware\": \"1 \u00b7 Hardware minimum\", \"2 \u00b7 Recommended hardware\": \"2 \u00b7 Hardware rekomendasi\", \"1 \u00b7 Minimum\": \"1 \u00b7 Minimum\", \"2 \u00b7 Recommended\": \"2 \u00b7 Rekomendasi\", \"Documented minimum collector spec\": \"Spesifikasi minimum collector sesuai dokumentasi\", \"Recommended spec + HA / redundancy\": \"Spesifikasi rekomendasi + HA / redundansi\", \"Quantity estimate \u00b7 confirm in CPQ\": \"Estimasi kuantitas \u00b7 konfirmasi di CPQ\", \"Per monitored DB instance \u00b7 confirm in CPQ\": \"Per instance DB termonitor \u00b7 konfirmasi di CPQ\", \"Planned additions\": \"Rencana penambahan\", \"Growth headroom %\": \"Headroom pertumbuhan %\", \"Module coverage by tier\": \"Cakupan modul per tier\", \"Published node tiers\": \"Tier node terpublikasi\", \"Published Premier node tiers\": \"Tier node Premier terpublikasi\", \"Self-Hosted infrastructure \u2014 Minimum vs Recommended\": \"Infrastruktur Self-Hosted \u2014 Minimum vs Rekomendasi\", \"Infrastructure \u2014 Minimum vs Recommended\": \"Infrastruktur \u2014 Minimum vs Rekomendasi\", \"Collectors & agents \u2014 Minimum vs Recommended\": \"Collector & agent \u2014 Minimum vs Rekomendasi\", \"Per-poller scalability limits (2026 guide)\": \"Batas skalabilitas per poller (panduan 2026)\", \"Entity weighting & units of measure\": \"Pembobotan entitas & satuan ukur\", \"Module license summary\": \"Ringkasan lisensi modul\", \"License summary\": \"Ringkasan lisensi\", \"License types\": \"Tipe lisensi\", \"DPA server & repository \u2014 Minimum vs Recommended\": \"Server DPA & repository \u2014 Minimum vs Rekomendasi\", \"DPA 2026.2 sizing brackets (per DPA server)\": \"Bracket sizing DPA 2026.2 (per server DPA)\", \"Recommended license tier\": \"Tier lisensi direkomendasikan\", \"Total required capacity\": \"Total kapasitas dibutuhkan\", \"Scale edition\": \"Edisi skala\", \"Polling engines required\": \"Polling engine dibutuhkan\", \"Additional web servers\": \"Web server tambahan\", \"Recommended Premier tier\": \"Tier Premier direkomendasikan\", \"Attached SaaS capacity\": \"Kapasitas SaaS terlampir\", \"Overage headroom\": \"Headroom overage\", \"Storage / WPM (included)\": \"Storage / WPM (termasuk)\", \"Network & Infrastructure entitlements\": \"Entitlement Network & Infrastructure\", \"Applications & Databases\": \"Aplikasi & Database\", \"Logs\": \"Log\", \"Total DPA licenses required\": \"Total lisensi DPA dibutuhkan\", \"DBSH licenses\": \"Lisensi DBSH\", \"DBSHDS licenses\": \"Lisensi DBSHDS\", \"DPA servers required\": \"Server DPA dibutuhkan\", \"Deployment bracket\": \"Bracket deployment\", \"Network & Infrastructure Observability\": \"Observabilitas Network & Infrastructure\", \"Self-Hosted (OSH) polling workload\": \"Beban kerja polling Self-Hosted (OSH)\", \"SaaS monitoring scope\": \"Cakupan monitoring SaaS\", \"Included components (Tier 2 \u00b7 no node impact in 2026.2)\": \"Komponen termasuk (Tier 2 \u00b7 tanpa dampak node di 2026.2)\", \"Server sizing workload\": \"Beban kerja sizing server\", \"Network devices\": \"Perangkat jaringan\", \"Wireless APs\": \"Wireless AP\", \"Hosts / servers\": \"Host / server\", \"Hypervisors / virtual hosts\": \"Hypervisor / host virtual\", \"Standalone VMs\": \"VM standalone\", \"Cloud services (non-host)\": \"Layanan cloud (non-host)\", \"Kubernetes containers\": \"Container Kubernetes\", \"Storage arrays\": \"Storage array\", \"NetFlow flows/sec (optional)\": \"NetFlow flow/detik (opsional)\", \"APM services\": \"Layanan APM\", \"Database instances\": \"Instance database\", \"Endpoints / URLs\": \"Endpoint / URL\", \"Protocols per endpoint\": \"Protokol per endpoint\", \"Public probe locations\": \"Lokasi probe publik\", \"Use private probes\": \"Gunakan private probe\", \"Number of private probes\": \"Jumlah private probe\", \"Synthetic transactions\": \"Transaksi sintetis\", \"RUM pageviews / month\": \"Pageview RUM / bulan\", \"Log ingest (GB / day)\": \"Ingest log (GB / hari)\", \"License tier\": \"Tier lisensi\", \"Licensed nodes (1 each)\": \"Node berlisensi (1 per node)\", \"Primary polling protocol\": \"Protokol polling utama\", \"Avg monitored elements per node\": \"Rata-rata elemen termonitor per node\", \"SAM component monitors\": \"Component monitor SAM\", \"SolarWinds agents\": \"Agent SolarWinds\", \"NetFlow flows/sec (on-prem)\": \"NetFlow flow/detik (on-prem)\", \"Concurrent web users\": \"Pengguna web bersamaan\", \"Full-license nodes (1 each)\": \"Node lisensi penuh (1 per node)\", \"Cloud VMs / small cloud resources\": \"VM cloud / resource cloud kecil\", \"Containers / K8s\": \"Container / K8s\", \"Thin APs\": \"Thin AP\", \"Edition\": \"Edisi\", \"Storage arrays (SRM)\": \"Storage array (SRM)\", \"WPM transactions\": \"Transaksi WPM\", \"Incident Response users\": \"Pengguna Incident Response\", \"SaaS network devices (collector)\": \"Perangkat jaringan SaaS (collector)\", \"SaaS servers \u2014 Agent\": \"Server SaaS \u2014 Agent\", \"SaaS servers \u2014 agentless\": \"Server SaaS \u2014 agentless\", \"SaaS flows/sec\": \"Flow SaaS/detik\", \"Self-hosted DB instances (DBSH)\": \"Instance DB self-hosted (DBSH)\", \"DBaaS instances (DBSHDS)\": \"Instance DBaaS (DBSHDS)\", \"VMware registered in DPA?\": \"VMware terdaftar di DPA?\", \"DPA Central concurrent users\": \"Pengguna bersamaan DPA Central\", \"Routers, switches, firewalls (1:1).\": \"Router, switch, firewall (1:1).\", \"10 share 1 entitlement.\": \"10 berbagi 1 entitlement.\", \"Agent or collector (1:1).\": \"Agent atau collector (1:1).\", \"VMware/Hyper-V/Nutanix host (1:1).\": \"Host VMware/Hyper-V/Nutanix (1:1).\", \"3 share 1 entitlement.\": \"3 berbagi 1 entitlement.\", \"AWS/Azure services, 3:1.\": \"Layanan AWS/Azure, 3:1.\", \"Drives dedicated flow collector sizing (\u226440,000 FPS each).\": \"Menentukan sizing flow collector khusus (\u226440.000 FPS per collector).\", \"Per active service, any # instances.\": \"Per layanan aktif, berapa pun jumlah instance.\", \"Per active instance.\": \"Per instance aktif.\", \"Distinct targets to monitor.\": \"Target berbeda yang dimonitor.\", \"e.g. HTTP(S), TCP, ICMP, DNS.\": \"mis. HTTP(S), TCP, ICMP, DNS.\", \"SolarWinds cloud test locations.\": \"Lokasi uji cloud SolarWinds.\", \"Agent-based probes hosted inside the customer network for internal endpoints.\": \"Probe berbasis agent di dalam jaringan pelanggan untuk endpoint internal.\", \"Added to location count. Each probe is a customer-hosted test location.\": \"Ditambahkan ke jumlah lokasi. Tiap probe adalah lokasi uji yang di-host pelanggan.\", \"Scripted multi-step journeys. 2 / bundle (5 checks each).\": \"Perjalanan multi-langkah terskrip. 2 / bundle (5 check per transaksi).\", \"Bundles of 100,000 pageviews.\": \"Bundle per 100.000 pageview.\", \"Priced per GB/day; org ceiling \u2248 200 GB/hr.\": \"Dihitung per GB/hari; plafon organisasi \u2248 200 GB/jam.\", \"Essentials: NPM, SAM, LA, IPAM, UDT, VNQM & Cloud. Advanced adds NTA, NCM, VMAN, SCM, anomaly-based alerting & the security vulnerability dashboard.\": \"Essentials: NPM, SAM, LA, IPAM, UDT, VNQM & Cloud. Advanced menambah NTA, NCM, VMAN, SCM, anomaly-based alerting & dashboard kerentanan keamanan.\", \"Servers, network devices, wireless controllers, autonomous APs, and any node with monitoring beyond ICMP status. Exclude ICMP-only status nodes (free).\": \"Server, perangkat jaringan, wireless controller, AP autonomous, dan node apa pun dengan monitoring di luar status ICMP. Tidak termasuk node status ICMP-only (gratis).\", \"Standard scales up to 1,500 nodes. Enterprise is required beyond 1,500 nodes and whenever Additional Polling Engines (APEs) are needed.\": \"Standard sampai 1.500 node. Enterprise wajib di atas 1.500 node dan saat Additional Polling Engine (APE) dibutuhkan.\", \"Sets per-poller element capacity: SNMPv2 100k \u00b7 SNMPv3 72k \u00b7 WMI/WinRM 20k (max 2,000 nodes), at 16 cores.\": \"Menentukan kapasitas elemen per poller: SNMPv2 100k \u00b7 SNMPv3 72k \u00b7 WMI/WinRM 20k (maks 2.000 node), pada 16 core.\", \"Interfaces, volumes, apps, component monitors per node. Typical 8\u201312.\": \"Interface, volume, aplikasi, component monitor per node. Umumnya 8\u201312.\", \"40k / APE.\": \"40k / APE.\", \"1,000 / poller.\": \"1.000 / poller.\", \"50k FPS / poller. Requires Advanced (NTA).\": \"50k FPS / poller. Butuh Advanced (NTA).\", \"25\u201350 / web server.\": \"25\u201350 / web server.\", \"50k FPS / poller.\": \"50k FPS / poller.\", \"Servers, network devices, wireless controllers, autonomous APs, paid ICMP nodes. Exclude ICMP-only status nodes (free).\": \"Server, perangkat jaringan, wireless controller, AP autonomous, node ICMP berbayar. Tidak termasuk node status ICMP-only (gratis).\", \"3 share 1 node.\": \"3 berbagi 1 node.\", \"10 share 1 node.\": \"10 berbagi 1 node.\", \"Agentless via Network Collector \u2014 up to 7,000 standard devices each.\": \"Agentless via Network Collector \u2014 hingga 7.000 perangkat standar per collector.\", \"Per-host agent.\": \"Agent per host.\", \"Via collector.\": \"Lewat collector.\", \"\u226440,000 flows/sec per collector.\": \"\u226440.000 flow/detik per collector.\", \"SQL Server, Oracle, MySQL, MariaDB, PostgreSQL, Db2, SAP ASE/HANA \u2014 incl. RDS, Aurora, Cloud SQL, Azure MI. 1 license each.\": \"SQL Server, Oracle, MySQL, MariaDB, PostgreSQL, Db2, SAP ASE/HANA \u2014 termasuk RDS, Aurora, Cloud SQL, Azure MI. 1 lisensi per instance.\", \"Azure SQL Database and other supported DBaaS targets. 1 license each.\": \"Azure SQL Database dan target DBaaS lain yang didukung. 1 lisensi per instance.\", \"Registering VMware raises DPA server CPU & RAM needs by ~50%.\": \"Mendaftarkan VMware menaikkan kebutuhan CPU & RAM server DPA ~50%.\", \"Only relevant with multiple DPA servers. DPA Central links servers into one view; co-locate it on a monitoring DPA server.\": \"Hanya relevan saat server DPA lebih dari satu. DPA Central menyatukan server dalam satu tampilan; tempatkan di salah satu server DPA monitoring.\", \"Size a full-stack SolarWinds Observability SaaS subscription across all modules \u2014 Network, Infrastructure, Application (APM), Database, Digital Experience (Synthetics & RUM), and Logs \u2014 using the \u00e0-la-carte, entity/consumption-based model. This calculator returns licensable quantities only (no pricing). Because the SaaS backend is hosted by SolarWinds, the only customer-side \\\"hardware\\\" to size is the collectors and agents that ship telemetry to the cloud.\": \"Hitung kebutuhan subscription SolarWinds Observability SaaS full-stack di semua modul \u2014 Network, Infrastructure, Application (APM), Database, Digital Experience (Synthetics & RUM), dan Logs \u2014 dengan model \u00e0-la-carte berbasis entitas/konsumsi. Kalkulator ini hanya menghasilkan kuantitas lisensi (tanpa harga). Karena backend SaaS di-host SolarWinds, satu-satunya \\\"hardware\\\" sisi pelanggan yang perlu di-sizing adalah collector dan agent pengirim telemetri ke cloud.\", \"Size the SolarWinds Observability Self-Hosted (OSH) Essentials or Advanced tier from monitored node capacity, then derive minimum and recommended self-hosted hardware. Both tiers use simple node-based licensing and scale through Standard and Enterprise editions. Poller sizing follows the 2026 scalability guide \u2014 per-poller capacity is protocol-dependent, not a flat element count.\": \"Hitung tier Essentials atau Advanced SolarWinds Observability Self-Hosted (OSH) dari kapasitas node termonitor, lalu turunkan hardware self-hosted minimum dan rekomendasi. Kedua tier memakai lisensi berbasis node sederhana dan menskala lewat edisi Standard dan Enterprise. Sizing poller mengikuti panduan skalabilitas 2026 \u2014 kapasitas per poller bergantung protokol, bukan jumlah elemen flat.\", \"Size the SolarWinds Observability Self-Hosted (OSH) Premier tier from monitored capacity, then derive minimum and recommended hardware for the self-hosted platform and the SaaS side (network collectors and per-host agents). Poller sizing follows the 2026 scalability guide \u2014 per-poller capacity is protocol-dependent, not a flat element count.\": \"Hitung tier Premier SolarWinds Observability Self-Hosted (OSH) dari kapasitas termonitor, lalu turunkan hardware minimum dan rekomendasi untuk platform self-hosted dan sisi SaaS (network collector dan agent per host). Sizing poller mengikuti panduan skalabilitas 2026 \u2014 kapasitas per poller bergantung protokol, bukan jumlah elemen flat.\", \"Size a SolarWinds DPA deployment from the number of monitored database instances. DPA is licensed per monitored database instance \u2014 current subscription licenses are DBSH (Database Self-Hosted, any edition of any supported database, VM metrics included) and DBSHDS (Database Self-Hosted DBaaS). Server and repository hardware follow the DPA 2026.2 system requirements, bracketed by instances per DPA server (max 250 each).\": \"Hitung deployment SolarWinds DPA dari jumlah instance database termonitor. DPA dilisensikan per instance database termonitor \u2014 lisensi subscription saat ini adalah DBSH (Database Self-Hosted, semua edisi semua database yang didukung, metrik VM termasuk) dan DBSHDS (Database Self-Hosted DBaaS). Hardware server dan repository mengikuti system requirements DPA 2026.2, dibagi per bracket instance per server DPA (maks 250 per server).\", \"Reach out to the Westcon team for licensing validation, CPQ quotes, and sizing reviews.\": \"Hubungi tim Westcon untuk validasi lisensi, penawaran CPQ, dan review sizing.\", \"How SaaS licensing counts things: each module is licensed separately by the number of active entities (or consumption) monitored in the previous calendar day. Smaller resources share an entitlement \u2014 VMs 3:1, cloud services 3:1, containers & wireless APs 10:1. ICMP-only status nodes are included free.\": \"Cara lisensi SaaS menghitung: tiap modul dilisensikan terpisah berdasarkan jumlah entitas aktif (atau konsumsi) yang termonitor pada hari kalender sebelumnya. Resource kecil berbagi entitlement \u2014 VM 3:1, layanan cloud 3:1, container & wireless AP 10:1. Node status ICMP-only gratis.\", \"Uptime checks = endpoints \u00d7 locations \u00d7 protocols. e.g. 20 endpoints \u00d7 2 locations \u00d7 1 protocol = 40 uptime checks. Each private probe you deploy counts as an additional location, so private probes are added to the location count before multiplying.\": \"Uptime check = endpoint \u00d7 lokasi \u00d7 protokol. mis. 20 endpoint \u00d7 2 lokasi \u00d7 1 protokol = 40 uptime check. Tiap private probe yang di-deploy dihitung sebagai lokasi tambahan, jadi private probe ditambahkan ke jumlah lokasi sebelum dikalikan.\", \"How licensing counts nodes: most monitored devices consume one node license each. ICMP-only status nodes (ping availability) are free, and cloud/hypervisor-discovered VMs are free until you assign additional monitoring \u2014 then each counts as one full node. Value-based fractional licensing is a Premier-only feature and does not apply to Essentials or Advanced.\": \"Cara lisensi menghitung node: sebagian besar perangkat termonitor memakai satu lisensi node. Node status ICMP-only (ping availability) gratis, dan VM hasil discovery cloud/hypervisor gratis sampai diberi monitoring tambahan \u2014 setelah itu dihitung satu node penuh. Lisensi fraksional berbasis nilai hanya fitur Premier dan tidak berlaku untuk Essentials atau Advanced.\", \"How licensing counts things: most devices use 1 full license each. Smaller resources share a license \u2014 cloud VMs 3-to-1, containers & thin wireless APs 10-to-1. Enter each type in its own field; sharing is applied automatically.\": \"Cara lisensi menghitung: sebagian besar perangkat memakai 1 lisensi penuh. Resource kecil berbagi lisensi \u2014 VM cloud 3-banding-1, container & thin wireless AP 10-banding-1. Isi tiap tipe di kolomnya masing-masing; pembagian dihitung otomatis.\", \"How DPA licensing counts: one license per monitored database instance. DBSH covers any edition of SQL Server, Oracle, MySQL, MariaDB, PostgreSQL, Db2, SAP ASE & HANA (cloud-hosted equivalents included) and bundles VM metrics \u2014 no VM Option needed. DBSHDS covers DBaaS targets such as Azure SQL Database. Licenses float: register more instances than licenses and assign them on the allocation page.\": \"Cara lisensi DPA menghitung: satu lisensi per instance database termonitor. DBSH mencakup semua edisi SQL Server, Oracle, MySQL, MariaDB, PostgreSQL, Db2, SAP ASE & HANA (termasuk versi cloud) dan sudah termasuk metrik VM \u2014 tanpa perlu VM Option. DBSHDS mencakup target DBaaS seperti Azure SQL Database. Lisensi bersifat floating: daftarkan lebih banyak instance dari lisensi dan alokasikan di halaman allocation.\"};\nvar SEL='h1,h2,h3,.sub,.panel-title,.field-label,.field-hint,.sub-head,.explainer,.badge,.cap,summary,.check span,.section-tag';\nfunction norm(t){return t.replace(/\\s+/g,' ').trim();}\nfunction apply(lang){\n  document.querySelectorAll(SEL).forEach(function(el){\n    if(!el.dataset.enKey){var k=norm(el.textContent);if(DICT[k]){el.dataset.enKey=k;el.dataset.enHtml=el.innerHTML;}else return;}\n    if(lang==='id'){el.textContent=DICT[el.dataset.enKey];}else{el.innerHTML=el.dataset.enHtml;}\n  });\n  document.querySelectorAll('.out-label').forEach(function(el){\n    var t=el.firstChild;if(!t||t.nodeType!==3)return;\n    if(!el.dataset.enLabel){var k=norm(t.nodeValue);if(DICT[k]){el.dataset.enLabel=k;}else return;}\n    t.nodeValue=(lang==='id'?DICT[el.dataset.enLabel]:el.dataset.enLabel)+' ';\n  });\n  document.querySelectorAll('.lang-btn').forEach(function(b){b.classList.toggle('active',b.dataset.lang===lang);});\n  document.documentElement.setAttribute('lang',lang==='id'?'id':'en');\n  try{localStorage.setItem('swsizing-lang',lang);}catch(e){}\n}\ndocument.querySelectorAll('.lang-btn').forEach(function(b){b.addEventListener('click',function(){apply(b.dataset.lang);});});\nvar saved='en';try{saved=localStorage.getItem('swsizing-lang')||'en';}catch(e){}\nif(saved==='id')apply('id');\n})();\n</script>\n</body>\n</html>\n";

export default {
  async fetch(request) {
    return new Response(HTML, {
      headers: { "content-type": "text/html;charset=UTF-8" }
    });
  }
};
